L["A dark edge around the letters on DaylightUI's frames, so text stays readable over a busy world."] = "Темный край вокруг букв на рамках DaylightUI, чтобы текст читался на пестром фоне."
L["A dash ( - )"] = "Дефис ( - )"
L["A debuff you can remove, as tiles show it."] = "Отрицательный эффект, который вы можете снять, как его показывают плитки."
L["A done objective stays, dimmed with a tick. When off, it disappears once it's done."] = "Выполненная задача остается, затемненная и с галочкой. Если выключено, она исчезает после выполнения."
L["A dot ( · )"] = "Точка ( · )"
L["A dragon wrapped around the end of an elite's or boss's bar, in gold, or silver for a rare."] = "Дракон, обвивающий конец полосы элиты или босса: золотой, а у редкого – серебряный."
L["A frame dropped in unlock mode, a spell placed in the Cooldown Manager editor, a click-cast bound. The game has no sound of its own for these."] = "Рамка отпущена в режиме перемещения, заклинание поставлено в редакторе трекера восстановления, назначено заклинание на кнопку мыши. У игры для этого нет своих звуков."
L["A framed panel behind the bar."] = "Подложка с каймой под панелью."
L["A friendly player's <guild> under their name, smaller."] = "<Гильдия> союзного игрока под его именем, помельче."
L["A gradient per point (Gradients page)"] = "Градиент для каждого приема (страница «Градиенты»)"
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "Зеленая полоска на индикаторе здоровья для входящего исцеления, как на рамках портретов."
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "Убийство или предмет для задания ненадолго появляется вверху экрана, небольшим текстом с полосой прогресса. Выключите, чтобы видеть вместо этого желтую строку игры. Перемещается в режиме перемещения."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "Линия на индикаторах здоровья противников там, где начинают работать ваши добивающие приемы. Конец полосы до нее подсвечивается акцентным цветом, когда здоровья у противника так мало. Для вашего класса: воины (Казнь) и паладины (Молот гнева)."
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "Полоса маны, ярости или энергии под здоровьем. Если выключено, вся рамка – здоровье."
L["A mark just left of the bar of anything your quests still need. Not inside instances."] = "Отметка слева от полосы у всего, что еще нужно для ваших заданий. Не в подземельях."
L["A member's border turns red while something is attacking them."] = "Кайма участника краснеет, пока его кто-то атакует."
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "Кольцо участника (или вкладка имени без портрета) краснеет, пока его кто-то атакует."
L["A name for the new group:"] = "Название новой группы:"
L["A name for the new profile (a copy of %s):"] = "Название нового профиля (копия %s):"
L["A new profession"] = "Новая профессия"
L["A new profile, made from %s with your picks."] = "Новый профиль, созданный из %s с вашим выбором."
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "Название новой зоны всплывает вверху экрана с тонкой линией под ним, затем подзона и статус PvP; у подзоны – только ее название, мелко. Заменяет текст зоны игры. Зависит от эффектов движения (Общие > Внешность)."
L["A note for %s:"] = "Заметка для %s:"
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "Бледная полоска на индикаторе здоровья для поглощающего щита, как на рамках портретов."
L["A panel behind the whole bar, so its buttons sit on one strip."] = "Подложка под всей панелью, чтобы кнопки стояли на одной полосе."
L["A panel behind the whole bar."] = "Подложка под всей панелью."
L["A player's <guild> under their name, smaller."] = "<Гильдия> игрока под его именем, помельче."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "Заклинания игрока – в цвете его класса или в градиенте класса при двухцветной заливке. Заклинания существ сохраняют стиль заливки. Не с градиентом Daylight."
L["A player's name in their class color; other units in their reaction's color."] = "Имя игрока в цвете его класса; остальные – в цвете их отношения."
L["A pressed button's icon sinks in a little and springs back as you let go."] = "Значок нажатой кнопки чуть утапливается и пружинит обратно, когда вы ее отпускаете."
L["A pulsing border while the spell's proc alert is up."] = "Пульсирующая кайма, пока активно оповещение о срабатывании заклинания."
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "Задание, готовое к сдаче, показывает только название. Задание на время никогда не сворачивается."
L["A quest you've failed, like a timed one that ran out."] = "Проваленное задание, например задание на время, которое истекло."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "Кольцо на внешнем конце. У игроков – значки классов, у НИП – их лицо. Нужна рамка высотой не меньше 20."
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "Круглый значок с портретом или тонкая полоса с портретом рядом и именем сверху."
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "Второй счетчик урона в отдельном окне, для двух списков сразу: например, лечение рядом с уроном. Наведите курсор, чтобы увидеть те же кнопки."
L["A set already has that name."] = "Набор с таким названием уже есть."
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "Щит: полоса пустеет по мере поглощения урона, на ней – оставшийся объем. Или по времени, как у любого эффекта."
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "Повышение навыка показывает новый уровень из максимума: Портняжное дело 152 / 225. Следующие повышения обновляют ту же строку."
L["A slash ( / )"] = "Косая черта ( / )"
L["A slim bar under the tooltip of a player or creature."] = "Тонкая полоса под подсказкой игрока или существа."
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "Ячейка с такой или меньшей прочностью получает янтарную точку и надпись «Скоро ремонт»."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "Маленькая метка БпН (персональный при надевании) или БпИ (персональный при использовании) в левом верхнем углу предметов в банке, пока предмет не стал персональным."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "Маленькая метка БпН (персональный при надевании) или БпИ (персональный при использовании) в левом верхнем углу, пока предмет не стал персональным."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "Маленькая метка БпН (персональный при надевании) или БпИ (персональный при использовании) в левом верхнем углу, пока предмет не стал персональным."
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "Маленькая кнопка «Копировать» в правом верхнем углу чата. Она открывает текст вкладки, чтобы его можно было выделить и нажать Ctrl+C. /dui copy делает то же самое."
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "Маленький значок у основания портрета (или в углу рамки без него), цвет которого показывает, насколько противник для вас сложен."
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "Маленький значок у основания портрета, цвет которого показывает, насколько противник для вас сложен. Нужен портрет или вкладка имени."
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "Небольшая полоса рядом с каждым участником группы, у которого призван питомец. Ваш питомец сохраняет свою рамку."
L["A small crown on the raid leader's tile."] = "Маленькая корона на плитке лидера рейда."
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "Маленькая вкладка с короной рядом с рамками группы или рейда, пока вы лидер группы или помощник в рейде. Она открывает проверку готовности, выбор роли, таймер пулла, метки целей и местности и «Все – помощники». Если выключено, все это доступно только через команды игры."
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "Маленькая точка в правом верхнем углу предметов в банке, входящих в один из ваших комплектов экипировки."
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "Маленькая точка в правом верхнем углу предметов, входящих в один из ваших комплектов экипировки."
L["A small gray line at the bottom of spell and item tooltips with its ID: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "Небольшая серая строка с ID внизу подсказок заклинаний и предметов: удобно для макросов, других модификаций и отчетов об ошибках. Значки эффектов используют подсказку самой игры, которая его показать не может."
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "Маленький значок в углу для отрицательного эффекта, который вы можете снять, с каймой в цвете его типа."
L["A small mana, rage or energy number on the power bar."] = "Небольшое число маны, ярости или энергии на полосе ресурса."
L["A small pet bar beside each party member whose pet is out."] = "Небольшая полоса питомца рядом с каждым участником группы, у которого призван питомец."
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "Маленький череп на портрете, когда вашего периодического урона хватает, чтобы добить цель."
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "Маленький череп за концом полосы, когда вашего периодического урона хватает, чтобы добить противника."
L["A small soft drop shadow under text."] = "Небольшая мягкая тень под текстом."
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "Маленький квадрат слева от рамки: красный, когда питомец недоволен, желтый – когда спокоен, зеленый – когда доволен. Наведите курсор, чтобы увидеть урон, преданность и рацион."
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "Маленькая метка после названия элитного, подземельного, рейдового или PvP-задания, здесь и в журнале заданий на карте."
L["A small time at the bottom of the map. Hover it for both local and server time."] = "Небольшие часы внизу карты. Наведите курсор, чтобы увидеть местное и серверное время."
L["A small zone name over each group of quests, the zone you're in first."] = "Небольшое название зоны над каждой группой заданий, сначала зона, в которой вы находитесь."
L["A soft glow in the threat color around the health bar."] = "Мягкое свечение цвета угрозы вокруг индикатора здоровья."
L["A soft light behind the arrow, in its color."] = "Мягкий свет за стрелкой, в ее цвете."
L["A soft light in the line's color runs across it as it comes in or adds up."] = "Мягкий свет цвета строки пробегает по ней, когда она появляется или пополняется."
L["A soft light round the frame in the debuff's type color."] = "Мягкий свет вокруг рамки в цвете типа отрицательного эффекта."
L["A soft light round the tile in the debuff's type color."] = "Мягкий свет вокруг плитки в цвете типа отрицательного эффекта."
L["A soft shadow round each button."] = "Мягкая тень вокруг каждой кнопки."
L["A soft, minimal interface."] = "Мягкий минималистичный интерфейс."
L["A soft, warm chime when a tracked quest is ready to hand in."] = "Мягкий теплый звон, когда отслеживаемое задание готово к сдаче."
L["A space"] = "Пробел"
L["A spell that just lit up, like Overpower or Execute."] = "Только что подсветившееся заклинание, например Превосходство или Казнь."
L["A spell with charges: the bar is cut into one piece per charge."] = "Заклинание с зарядами: полоса разбита на части по числу зарядов."
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "Значок заклинания вспыхивает один раз, когда завершается настоящее восстановление (не глобальное). Нужны эффекты движения (Общие > Внешность)."
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "Значок заклинания сереет, пока оно восстанавливается. Глобальное восстановление не учитывается."
L["A square minimap in the panel. Scroll to zoom."] = "Квадратная мини-карта на панели. Колесико мыши меняет масштаб."
L["A stun, fear, polymorph and the like, as a bigger icon beside the bar's end."] = "Оглушение, страх, превращение и подобное – крупным значком рядом с концом полосы."
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "Символ на карте мира у каждой пристани и башни дирижаблей. Наведите курсор, чтобы узнать, куда идет рейс."
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "Символ на карте мира у каждого входа в подземелье и рейд. Наведите курсор, чтобы узнать название."
L["A thin bar under the name."] = "Тонкая полоса под именем."
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "Тонкая линия поперек полос там, где ваша угроза сорвет противника: 110% от угрозы танка в ближнем бою, 130% в дальнем. Не показывается на боссе: игра скрывает его числа."
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "Тонкая полоска маны вдоль нижнего края полосы ресурса, пока облик скрывает вашу ману."
L["A thin mana, rage or energy bar at the foot of each tile."] = "Тонкая полоса маны, ярости или энергии внизу каждой плитки."
L["A thin outline on chat text."] = "Тонкий контур у текста чата."
L["A thin power bar under each pet's health."] = "Тонкая полоса ресурса под здоровьем каждого питомца."
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "Тонкая полоса под мини-картой: золото, экипировка, место в сумках, друзья в сети. Наведите курсор для подробностей, щелкните, чтобы открыть окно."
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "Чем тоньше контур, тем больше цвета в каждой точке. 0 – без контура."
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "Подсказка к чему-то в мире (существу, игроку, почтовому ящику) медленно исчезает, когда курсор уходит, как в игре. Если выключено, она пропадает сразу."
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "Дорожка маленьких ромбов от ваших ног к маркеру, плывущих к нему. Как и маркер, исчезает, когда вы оказываетесь в области задания на карте."
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "Двухминутный обзор всего, что умеет DaylightUI, с выбором по ходу. Ничего не сохраняется, пока вы не закончите."
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "Теплая полоса света растекается по верху экрана, выкатывается ваш новый уровень, а под ним проступает то, что вы получили – вместо баннера игры. Зависит от эффектов движения (Общие > Внешность)."
L["A warning when your health or mana drops low."] = "Предупреждение, когда здоровья или маны становится мало."
L["A word when a fight starts and ends."] = "Слово в начале и в конце боя."
L["AFK"] = "Отсутствует"
L["AVOIDABLE"] = "Можно избежать"
L["AWAY"] = "Отсутствует"
L["Abandon"] = "Отменить"
L["Abandon \"%s\"?"] = "Отменить задание \"%s\"?"
L["Abandon?"] = "Отменить?"
L["About 1 in %d of your attacks hits for double damage."] = "Примерно 1 из %d ваших атак наносит двойной урон."
L["About 1 in %d of your shots hits for double damage."] = "Примерно 1 из %d ваших выстрелов наносит двойной урон."
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "Примерно 1 из %d ваших заклинаний наносит критический удар в полтора раза сильнее."
L["Above"] = "Сверху"
L["Above or below the frame, the bar is as wide as the frame. Off: the Width below."] = "Над или под рамкой полоса шириной с рамку. Если выключено – ширина ниже."
L["Above or below the frame: moves the bar sideways from the middle."] = "Над или под рамкой: сдвигает полосу вбок от середины."
L["Above or below the frame: moves the bar up or down."] = "Над или под рамкой: сдвигает полосу вверх или вниз."
L["Above the frame"] = "Над рамкой"
L["Above the health bar"] = "Над индикатором здоровья"
L["Above the name tab by default, running inward. Yours come first."] = "По умолчанию над вкладкой имени, к центру. Ваши идут первыми."
L["Above your debuffs, from the right."] = "Над вашими отрицательными эффектами, справа."
L["Absorb shields"] = "Поглощающие щиты"
L["Absorbs"] = "Щиты"
L["Accent"] = "Акцент"
L["Accent color"] = "Акцентный цвет"
L["Accent follows Appearance, including the Daylight gradient."] = "«Акцент» следует настройке «Внешность», включая градиент Daylight."
L["Accent follows the accent you picked on the General page, gradient and all."] = "«Акцент» следует акценту, выбранному на странице «Общие», вместе с градиентом."
L["Accent follows your accent color (General > Appearance), or pick your own."] = "«Акцент» следует вашему акцентному цвету (Общие > Внешность), или выберите свой."
L["Accept"] = "Принять"
L["Accept key"] = "Клавиша принятия"
L["Accept quests automatically"] = "Принимать задания автоматически"
L["Account"] = "Учетная запись"
L["Achievement announcements."] = "Объявления о достижениях."
L["Achievement color"] = "Цвет достижений"
L["Achievements"] = "Достижения"
L["Across"] = "Поперек"
L["Across the bar"] = "На полосе"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "«На полосе» оставляет его внутри. Любое другое место ставит его туда, на рамку или вокруг нее, чтобы длинному имени хватило места. Его также можно перетащить в режиме дизайна."
L["Across the bar keeps the alignment below. Beside the tile needs space between tiles."] = "«На полосе» сохраняет выравнивание ниже. «Рядом с плиткой» требует промежутков между плитками."
