L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "Добавляется кнопкой «Добавить элемент» в режиме дизайна. Перетащите его на образце, чтобы переместить. До трех частей в одной строке, каждая своим цветом."
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "Добавляется кнопкой «Добавить элемент» в режиме дизайна: еще один ряд аур со своим фильтром."
