L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "Добавляет теплую полосу внутри черного контура, подсвеченную сверху. Если выключено, кайма – простая темная линия."
L["Adds about %.0f damage per second to your melee attacks."] = "Добавляет около %.0f ед. урона в секунду к вашим атакам в ближнем бою."
L["Adds about %.0f damage per second to your shots."] = "Добавляет около %.0f ед. урона в секунду к вашим выстрелам."
