L["An arrow on your screen that points to the nearest mob or object you still need for the quest you picked, then to the quest giver once it's ready, with the yards under it. Nothing goes on the map. Needs the QuestieDB addon."] = "Стрелка на экране, указывающая на ближайшее существо или предмет, еще нужные для выбранного задания, а когда оно готово – на того, кто его выдал; под ней расстояние. На карте ничего не появляется. Нужна модификация QuestieDB."
L["An item's green Equip lines in a few words (\"Improves your chance to hit by 1%\" reads \"+1% Hit\"), and every stat in a color of its own: each school, hit, crit, spell power, healing, the base stats. Procs and use effects stay as they are."] = "Зеленые строки «Если на персонаже» в нескольких словах («Повышает вероятность попадания на 1%» читается как «+1% к меткости»), и у каждой характеристики свой цвет: каждая школа, меткость, крит, сила заклинаний, исцеление, основные характеристики. Срабатывания и эффекты использования остаются как есть."
L["An objective you've finished."] = "Выполненная задача."
