L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "Скашивает оба конца каждой строки. Если выключено, концы прямые."
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "Скашивает правый конец каждой плитки, как у вашей рамки; полосы повторяют его."
L["Cuts one end of each pet bar at an angle. When off, the ends are straight."] = "Скашивает один конец каждой полосы питомца. Если выключено, концы прямые."
L["Cuts the end of the bar at an angle. When off, the end is straight."] = "Скашивает конец полосы. Если выключено, конец прямой."
L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Скашивает конец индикатора заклинаний фокуса. Если выключено, конец прямой. Не когда он внутри рамки."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Скашивает конец индикатора заклинаний цели. Если выключено, конец прямой. Не когда он внутри рамки."
L["Cuts the frame's inner end at an angle; the bars follow it."] = "Скашивает внутренний конец рамки; полосы повторяют его."
L["Cuts the left end at an angle; the bars follow it."] = "Скашивает левый конец; полосы повторяют его."
L["Cuts the right end of each bar at an angle. When off, the ends are square."] = "Скашивает правый конец каждой полосы. Если выключено, концы прямые."
L["Cuts the right end at an angle; the bars and an attached cast bar follow it."] = "Скашивает правый конец; полосы и прикрепленный индикатор заклинаний повторяют его."
L["Cuts the right end at an angle; the bars follow it."] = "Скашивает правый конец; полосы повторяют его."
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "Сцены и вступительные ролики сразу пропускаются. Удерживайте Shift в начале, чтобы посмотреть."
