L["DISPELS"] = "Развеивание"
L["DND"] = "Не беспокоить"
L["DPS / Tank"] = "DPS / Tank"
L["DPS / Tank (as it comes)"] = "DPS / Tank (как есть)"
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tank в спокойном варианте для заданий: панели команд и ваша рамка затухают через некоторое время после боя (возвращаются при наведении курсора, в бою или при ранении), счетчик урона сначала свернут (один щелчок по вкладке панели выдвигает его), мини-карта чуть меньше, а индикатор опыта показывает проценты. В подземельях, рейдах, на полях боя и аренах ничего не затухает (Общие > Внешность, «Затухание только в открытом мире»). Выберите его выше, чтобы использовать. Если в текущем профиле панели команд перемещены, предлагает перенести их."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tank с группой и рейдом в виде квадратных плиток под вами (вы тоже, на них недостающее здоровье, развеивание хорошо видно), а ваша рамка и рамка цели чуть приподняты. Все, что он задает, есть на страницах «Группа» и «Рейд»; любую рамку можно переместить в режиме перемещения. Выберите его выше, чтобы использовать. Если в текущем профиле панели команд перемещены, предлагает перенести их."
