L["Daylight UI couldn't skin %s %s: it's left as it is."] = "Daylight UI не удалось оформить %s %s: оставлено как есть."
L["Daylight gradient"] = "Градиент Daylight"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "Daylight – теплая полоса внутри темного контура, «Плоский» – простой контур. При «Нет» значок заполняет всю кнопку."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame (Extras > Frame style). Each style keeps its own heights."] = "Daylight: рамка с именем во вкладке сверху и полосой ресурса внутри. Лента: тонкая полоса с именем и здоровьем над ней и ресурсом тонкой линией под ней. «По умолчанию» использует стиль, заданный для всех рамок (Дополнительно > Стиль рамок). У каждого стиля свои высоты."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight: рамка с именем во вкладке сверху и полосой ресурса внутри. Лента: тонкая полоса с именем и здоровьем над ней и ресурсом тонкой линией под ней. Каждая рамка может выбрать свой стиль на своей странице."
L["DaylightUI"] = "DaylightUI"
L["DaylightUI (General)"] = "DaylightUI (Общие)"
L["DaylightUI Discord"] = "Discord DaylightUI"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "В DaylightUI новый мастер настройки. Пройдите обзор, чтобы увидеть все возможности, или оставьте свои настройки как есть."
L["DaylightUI is set up on this character. Reload to put it in place?"] = "DaylightUI настроен на этом персонаже. Перезагрузить, чтобы применить?"
L["DaylightUI look for speech bubbles (say, yell, party). Instances keep the game's bubbles, since addons can't change them there."] = "Вид DaylightUI для облачков речи (речь, крик, группа). В подземельях остаются облачка игры: модификации не могут их там менять."
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "DaylightUI переместил список заданий под панель. Перезагрузить, чтобы применить?"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "DaylightUI применил макет режима редактирования этого профиля. Перезагрузить, чтобы использовать?"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "DaylightUI заменяет рамки, панели, сумки, чат и многое другое мягким минималистичным оформлением. Давайте настроим этого персонажа."
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "DaylightUI сохранил положение окна добычи. Перезагрузить, чтобы применить?"
L["DaylightUI saved the quest tracker's position. Reload to put it in place?"] = "DaylightUI сохранил положение списка заданий. Перезагрузить, чтобы применить?"
L["DaylightUI style Legacy window"] = "Окно наследия в стиле DaylightUI"
