L["DaylightUI style inspect window"] = "Окно осмотра в стиле DaylightUI"
L["DaylightUI style layout and look for the game's Cooldown Manager. When off, it's left exactly as the game draws it and /cdm opens the game's own settings."] = "Раскладка и вид в стиле DaylightUI для трекера восстановления игры. Если выключено, он остается в точности таким, как его рисует игра, а /cdm открывает собственные настройки игры."
L["DaylightUI style mailbox"] = "Почтовый ящик в стиле DaylightUI"
L["DaylightUI style profession window"] = "Окно профессий в стиле DaylightUI"
