L["DaylightUI tracker (works with Questie)"] = "Список заданий DaylightUI (работает с Questie)"
L["DaylightUI updated its layout. Reload to put it in place?"] = "DaylightUI обновил свою раскладку. Перезагрузить, чтобы применить?"
