L["Drag a piece to move it. Click it for its settings; the arrow keys then nudge it."] = "Перетащите элемент, чтобы переместить его. Щелкните по нему, чтобы открыть его настройки; затем стрелки сдвигают его."
L["Drag it to an action bar."] = "Перетащите на панель команд."
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "Перетаскивайте элементы в предпросмотре: каждый остается там, где вы его отпустили, или цепляется за точку рядом. Щелкните по элементу, и стрелки будут сдвигать его (с Shift — на больший шаг). Каждое перемещение меняет те же настройки, что и карточки ниже."
L["Drag to move it, or click for its settings."] = "Перетащите, чтобы переместить, или щелкните, чтобы открыть настройки."
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "Перетащите, чтобы переместить. Отпустите рядом с другим элементом, чтобы прикрепить к нему, оттащите, чтобы открепить. «Удалить» убирает его."
L["Dragon around the portrait"] = "Дракон вокруг портрета"
L["Dragon color"] = "Цвет дракона"
L["Drop an item here"] = "Перетащите предмет сюда"
L["Druid"] = "Друид"
L["Druid mana in forms"] = "Мана друида в облике"
L["Dungeon"] = "Подземелье"
L["Dungeon Journal"] = "Атлас подземелий"
L["Dungeon and raid entrances"] = "Входы в подземелья и рейды"
L["Dungeon tag color"] = "Цвет метки подземелья"
L["Dungeons, raids and battlegrounds"] = "Подземелья, рейды и поля боя"
L["Durability"] = "Прочность"
L["Durability %s"] = "Прочность %s"
L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "Во время проверки готовности на каждом участнике галочка, крестик или вопросительный знак: готов, не готов или еще не ответил. Они остаются на несколько секунд после окончания проверки."
L["ENEMY TAKEN"] = "ПОЛУЧЕНО ПРОТИВНИКАМИ"
L["Each bar in its player's class color, or all in one color."] = "Каждая полоса в цвете класса ее игрока или все одним цветом."
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "Рука каждой полосы (или атака в очереди) и время до следующего удара, прямо на полосе."
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "Форма каждой панели и когда она видна. Изменения применяются сразу. Перемещайте панели в режиме перемещения."
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "Размер, форма каждой панели и когда она видна. Выберите панель в списке «Настройки для»."
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "Каждый персонаж использует профиль (по одному на набор талантов при двойной специализации). Все на каждой странице меняет используемый профиль."
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere with the chest button in your bags, or /dui bank. When off, the button goes away and nothing new is saved."] = "Сумки каждого персонажа сохраняются при выходе из игры, а банк — при каждом посещении банкира. Смотрите их где угодно кнопкой с сундуком в сумках или командой /dui bank. Если выключено, кнопка пропадает и ничего нового не сохраняется."
L["Each combo point you build on your target."] = "Каждый прием серии, накопленный на цели."
L["Each icon darkens like a clock as its time runs out."] = "Каждый значок темнеет, как циферблат, по мере истечения времени."
L["Each icon's width and height."] = "Ширина и высота каждого значка."
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "Название и уровень каждого предмета рядом с его значком. Если выключено, видны только значки с уровнем предмета в углу, а для модели остается больше места."
L["Each its own"] = "У каждого свой"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "Каждый удар правой рукой наносит от %.0f до %.0f ед. урона без учета брони."
L["Each member's health written on their tile."] = "Здоровье каждого участника на его ячейке."
L["Each member's name on their tile."] = "Имя каждого участника на его ячейке."
L["Each objective line under a quest."] = "Каждая строка задачи под заданием."
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "Каждый, кто шепчет вам, получает свою вкладку рядом с остальными, а шепот также виден в основной вкладке. Если выключено, шепот виден только в основной вкладке."
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "Каждое деление наклонено, как скошенные края рамок. Если выключено, края прямые."
L["Each pip's end cut at an angle, like the health bar's."] = "Край каждого деления срезан под углом, как у шкалы здоровья."
L["Each quest's level in front of its title, like [15]."] = "Уровень каждого задания перед его названием, например [15]."
L["Each quest's title in the tracker."] = "Название каждого задания в списке заданий."
L["Each shot hits for %.0f to %.0f before armor."] = "Каждый выстрел наносит от %.0f до %.0f ед. урона без учета брони."
L["Each square darkens like a clock as your spell runs out."] = "Каждый квадрат темнеет, как циферблат, по мере окончания вашего заклинания."
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "У каждого набора талантов свой макет. «Изменить макет» и «Копировать из» работают с этим."
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "Каждый текст обновляется при изменении. Наведите курсор для подробностей: золото всех персонажей, каждый предмет экипировки, каждая сумка, кто в сети."
L["Each threat bar in its player's class color, or all in one color."] = "Каждая полоса угрозы в цвете класса ее игрока или все одним цветом."
L["Early start"] = "Ранний старт"
L["Earned"] = "Заработанные"
L["Earned this session"] = "Заработано за сеанс"
L["Eases class, reaction and power colors toward gray for a gentler look."] = "Смягчает цвета классов, отношения и ресурсов к серому для более спокойного вида."
L["Edit"] = "Изменить"
L["Edit Mode hasn't loaded its layouts yet; try again in a moment"] = "Режим редактирования еще не загрузил макеты; повторите чуть позже"
L["Edit Mode is open; close it first"] = "Открыт режим редактирования; сначала закройте его"
L["Edit layout"] = "Изменить макет"
L["Edit listing"] = "Изменить список"
L["Edit on screen"] = "Изменить на экране"
L["Eight candles, and hardly a dent in them! Here, pick something for your trouble."] = "Восемь свечей, и почти целые! Вот, выбери что-нибудь за труды."
