L["Elite crest"] = "Герб элиты"
L["Elite dragon"] = "Дракон элиты"
L["Elite or rare"] = "Элита или редкий"
L["Elite tag color"] = "Цвет метки элиты"
L["Elwynn Forest"] = "Элвиннский лес"
L["Emote color"] = "Цвет эмоций"
L["Emotes like /wave and /e text."] = "Эмоции вроде /wave и текст /e."
L["Empty"] = "Пусто"
L["Empty pips"] = "Пустые деления"
L["Empty slots"] = "Пустые ячейки"
L["Enchant"] = "Зачаровать"
L["End"] = "End"
L["Ends in %d day"] = "Закончится через %d дн."
L["Ends in %d days"] = "Закончится через %d дн."
L["Ends in %d hour"] = "Закончится через %d ч."
L["Ends in %d hours"] = "Закончится через %d ч."
L["Ends within the hour"] = "Закончится в течение часа"
L["Enemy damage taken"] = "Полученный противниками урон"
L["Enemy pets and totems"] = "Питомцы и тотемы противников"
L["Enemy pets and totems get a look of their own, totems in their element's color. In battlegrounds they're all red: the game hides which totem it is. When off, the game's setting for their plates is turned off too."] = "Питомцы и тотемы противников выглядят по-своему, тотемы — в цвете своей стихии. На полях боя они все красные: игра скрывает, что это за тотем. Если выключено, игровая настройка их индикаторов тоже отключается."
L["Enemy plates: the health bar, the name under it, casts, your debuffs and crowd control. Friendly plates are simpler."] = "Индикаторы противников: шкала здоровья, имя под ней, заклинания, ваши отрицательные эффекты и контроль. Индикаторы союзников проще."
L["Energy"] = "Энергия"
L["Enhancement"] = "Совершенствование"
L["Enter"] = "Enter"
L["Enter or Space"] = "Enter или Пробел"
L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "Enter отвечает «да», когда вас о чем-то спрашивают: приглашение в группу, общее задание, призыв, воскрешение. Никогда — на то, что привязывает предмет, разыгрывает добычу или стоит денег, и никогда в бою. Сделать таверну своим домом можно и клавишей принятия."
L["Entering and leaving combat"] = "Вход в бой и выход из него"
L["Epic (purple) and up"] = "Эпические (фиолетовые) и выше"
L["Epic mount fund: %d%%. Keep saving!"] = "Копилка на эпического скакуна: %d%%. Продолжайте копить!"
L["Equipment sets"] = "Комплекты экипировки"
L["Error messages"] = "Сообщения об ошибках"
L["Error text"] = "Текст ошибок"
L["Error text in DaylightUI style"] = "Текст ошибок в стиле DaylightUI"
L["Esc"] = "Esc"
L["Every bag in one window, with search, sorting and categories."] = "Все сумки в одном окне, с поиском, сортировкой и категориями."
L["Every color in the quest tracker."] = "Все цвета списка заданий."
L["Every debuff on you, over your frame. Off by default: your buff bars show them too."] = "Все отрицательные эффекты на вас, над вашей рамкой. По умолчанию выключено: их показывают и панели эффектов."
L["Every empty slot"] = "Каждая пустая ячейка"
L["Every font"] = "Все шрифты"
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "Полоса каждой руки в цвете вашего класса или в градиенте класса при двухцветной заливке. Атака в очереди сохраняет свой цвет. Не работает с градиентом Daylight."
L["Every header in this one color."] = "Все заголовки этим цветом."
L["Every health bar's color when Health bar color is One color."] = "Цвет всех шкал здоровья, когда «Цвет индикатора здоровья» — «Один цвет»."
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "Каждый предмет, который вы перетащили в группу или переместили через Alt + правый щелчок, возвращается в свою группу."
L["Every line in the tooltips. General uses the font on General > Appearance."] = "Все строки подсказок. «Общий» использует шрифт из раздела «Общий > Внешность»."
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "Все строки остаются, пока не истечет время самой новой, затем исчезают вместе. Если выключено, каждая строка исчезает сама по себе."
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "Каждая вторая строка на бледной полосе в характеристиках и длинных списках, чтобы строки было легче читать."
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "Все части DaylightUI и что они делают. Отключите ненужные; изменения вступят в силу после перезагрузки."
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "Затухание всех частей в одном месте. Каждая — та же настройка, что и на странице этой части."
