L["Fade out of combat"] = "Затухать вне боя"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "Затухать вне боя: тускнеет через некоторое время после боя и возвращается в бою. Затухать в бою: тускнеет через некоторое время после начала боя и возвращается после него. Затухать до наведения: остается тусклым, пока на него не наведен курсор. Только при изменениях: скрыт вне боя, виден в бою и ненадолго появляется при изменениях (получен или пропал эффект, здоровье, прогресс задания, опыт)."
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "Затухать вне боя: тускнеет через некоторое время после боя и возвращается в бою. Затухать в бою: тускнеет через некоторое время после начала боя и возвращается после него. Затухать до наведения: остается тусклым, пока на него не наведен курсор. Только при изменениях: скрыт вне боя, виден в бою и ненадолго появляется при изменениях (получен или пропал эффект, здоровье, прогресс задания, опыт). Скрыто (в бою, вне боя или всегда): не виден, и по его кнопкам нельзя щелкнуть."
