L["Group keeps each raid group together. Group, then role does too, with tanks, then healers, then damage at the top of each. The others list everyone in one order and wrap by tiles per line."] = "«Группа» держит каждую группу рейда вместе. «Группа, затем роль» тоже, причем в каждой сверху танки, затем лекари, затем бойцы. Остальные варианты выстраивают всех в одном порядке с переносом по числу ячеек в строке."
L["Group keeps the party's own order."] = "«Группа» сохраняет порядок самой группы."
