L["Hide global cooldown swipe"] = "Скрыть затемнение общего восстановления"
L["Hide keeps its gap: the other spells don't move."] = "«Скрыть» сохраняет пустое место: другие заклинания не сдвигаются."
L["Hide lower ranks"] = "Скрыть низшие ранги"
L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "«Скрыть» показывает заклинание, только пока оно восстанавливается. «Только когда доступно» показывает его, когда его можно применить: Ответный удар после парирования, Превосходство после уклонения, Казнь по цели с малым запасом здоровья. Оба сохраняют пустое место: другие заклинания не сдвигаются."
L["Hide while mounted"] = "Скрывать верхом"
L["Hides the higher raid groups, e.g. 4 for a 20-player raid."] = "Скрывает старшие группы рейда, например 4 для рейда на 20 игроков."
L["Hides the number while a minute or more is left, so long buffs stay quiet."] = "Скрывает число, пока осталась минута или больше, чтобы долгие эффекты не отвлекали."
L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "Скрывает красный текст и голосовую реплику при слишком раннем нажатии кнопки: не хватает ярости, маны или энергии, еще не готово, вне зоны действия, нет цели. Полезные сообщения остаются: сумки полны, прервано, вне поля зрения, сообщения заданий."
L["Hiding"] = "Скрытие"
L["Highlight"] = "Подсветка"
L["Highlight color"] = "Цвет подсветки"
L["Highlights a spell that is active (an aura, auto attack, a stance) or being cast."] = "Подсвечивает активное заклинание (аура, автоатака, стойка) или применяемое."
L["History"] = "История"
L["Hold: move to another group"] = "Удерживать: переместить в другую группу"
