L["Hooked above %s"] = "Прикреплено сверху: %s"
L["Hooked below %s"] = "Прикреплено снизу: %s"
L["Hooked left of %s"] = "Прикреплено слева: %s"
L["Hooked right of %s"] = "Прикреплено справа: %s"
L["Horizontal (light at the full end)"] = "По горизонтали (светлее у полного конца)"
L["Hostile"] = "Противник"
L["Hover a button and press a key to bind it, or Escape to clear it. Click Okay when you're done. Out of combat only."] = "Наведите курсор на кнопку и нажмите клавишу, чтобы назначить ее, или Escape, чтобы очистить. Когда закончите, нажмите «ОК». Только вне боя."
L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "Наведите курсор, чтобы увидеть кнопки: бой (общий, текущий и прошлые бои по названию), режим и сброс."
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. Off shows it at the mouse."] = "При наведении на задание в журнале его подсказка появляется рядом с журналом, как в игровом журнале. Если выключено, она появляется у курсора."
L["Hovering an item, spell or quest link in chat shows its tooltip, just above the chat."] = "При наведении на ссылку на предмет, заклинание или задание в чате ее подсказка появляется прямо над чатом."
L["How big a crit on you pops. It starts at half this and settles back. The game's own is 60."] = "Насколько крупно выскакивает критический удар по вам. Он начинается с половины этого размера и возвращается. В игре — 60."
L["How big each buff icon is."] = "Размер значка каждого положительного эффекта."
L["How big each debuff icon is."] = "Размер значка каждого отрицательного эффекта."
L["How big each icon is."] = "Размер каждого значка."
L["How big each item slot is in the Bank and alts window."] = "Размер каждой ячейки в окне «Банк и другие персонажи»."
L["How big each item slot is in the bag."] = "Размер каждой ячейки в сумке."
L["How big each item slot is in the bank."] = "Размер каждой ячейки в банке."
L["How big every square is."] = "Размер каждого квадрата."
L["How big it is, as a percent of its normal size. This is Edit Mode's own size setting, kept in your Edit Mode layout."] = "Размер в процентах от обычного. Это собственная настройка размера режима редактирования, она хранится в вашем макете режима редактирования."
L["How big the PvP flag is."] = "Размер значка PvP."
L["How big the arrow is on your screen, yards text included."] = "Размер стрелки на экране вместе с текстом расстояния в метрах."
L["How big the clock is."] = "Размер часов."
L["How big the corner crown is."] = "Размер короны в углу."
L["How big the crowd control icon is."] = "Размер значка контроля."
L["How big the data texts are."] = "Размер информационных текстов."
L["How big the dispellable debuff's icon is."] = "Размер значка развеиваемого отрицательного эффекта."
L["How big the framerate is."] = "Размер частоты кадров."
L["How big the health text is on this frame."] = "Размер текста здоровья на этой рамке."
L["How big the health text on the tiles is."] = "Размер текста здоровья на ячейках."
L["How big the icons of buffs you can purge or steal are."] = "Размер значков положительных эффектов, которые можно рассеять или украсть."
L["How big the item names, counts and skill-up text are in the loot feed."] = "Размер названий предметов, количества и текста повышения навыков в ленте добычи."
L["How big the large health number is."] = "Размер крупного числа здоровья."
L["How big the leader crown is."] = "Размер короны лидера."
L["How big the leader's crown is."] = "Размер короны лидера."
L["How big the name is on this frame."] = "Размер имени на этой рамке."
L["How big the names on the tiles are."] = "Размер имен на ячейках."
L["How big the pets' health text is."] = "Размер текста здоровья питомцев."
L["How big the pets' names are."] = "Размер имен питомцев."
L["How big the portrait ring is next to the frame's height."] = "Размер кольца портрета относительно высоты рамки."
L["How big the quest marker is in the world, distance text included."] = "Размер метки задания в мире вместе с текстом расстояния."
L["How big the raid marker is."] = "Размер рейдовой метки."
L["How big the ready check answer is."] = "Размер ответа на проверку готовности."
L["How big the resting Zzz is."] = "Размер значка отдыха Zzz."
L["How big the role icon is."] = "Размер значка роли."
L["How big the round badge of an enemy pet or totem is."] = "Размер круглого значка питомца или тотема противника."
L["How big the square minimap is."] = "Размер квадратной мини-карты."
L["How big the window is."] = "Размер окна."
L["How big the window is. Other windows still open beside it when they fit."] = "Размер окна. Другие окна по-прежнему открываются рядом, если помещаются."
L["How big this extra text is."] = "Размер этого дополнительного текста."
L["How big your buff icons on friendly plates are."] = "Размер значков ваших положительных эффектов на индикаторах союзников."
L["How big your debuff icons are."] = "Размер значков ваших отрицательных эффектов."
L["How bright the light behind the arrow is."] = "Яркость света за стрелкой."
L["How bright the pips you haven't filled are, as a share of their color. Lower makes the filled ones stand out more."] = "Яркость незаполненных делений как доля их цвета. Чем ниже, тем заметнее заполненные."
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "Яркость неисследованных областей. При 100% они выглядят как исследованные."
L["How dark the shade that sweeps over a button on cooldown is."] = "Насколько темное затемнение проходит по кнопке во время восстановления."
L["How dark the shadow around DaylightUI's frames and windows is."] = "Насколько темная тень вокруг рамок и окон DaylightUI."
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set right here. A queued attack always keeps its own color."] = "Как заполняется полоса каждой руки: по одному цвету, градиентом Daylight (от синего к оранжевому, как на логотипе) или двухцветным градиентом для каждой руки, заданным прямо здесь. Атака в очереди всегда сохраняет свой цвет."
L["How every cast bar (yours, target's, focus's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set right here."] = "Как заполняются все индикаторы заклинаний (ваш, цели, фокуса): по одному цвету, градиентом Daylight (от синего к оранжевому, как на логотипе) или двухцветным градиентом для каждого вида применения, заданным прямо здесь."
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "Насколько выше курсора находится угол подсказки (меньше нуля — ниже)."
L["How far along that quest objective is (4/10, or 45%), small, beside the !."] = "Прогресс этой задачи (4/10 или 45%) мелким шрифтом рядом с !."
L["How far away plates show, in yards. 60 is the most the game allows."] = "Дальность показа индикаторов в метрах. 60 — максимум, который позволяет игра."
L["How far away the spot is."] = "Расстояние до точки."
L["How far from the target the numbers start."] = "На каком расстоянии от цели появляются числа."
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "Насколько сильно затухает. При 0 исчезает полностью. Никогда не больше «Видимости»."
L["How far past the name and bar a click still selects the unit."] = "Насколько за пределами имени и полосы щелчок все еще выбирает цель."
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "Насколько правее курсора находится угол подсказки (меньше нуля — левее)."
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "Насколько далеко может отдаляться камера. 100% — обычный предел игры; крайнее правое значение — максимум, который позволяет этот клиент. При 100% игровая настройка не меняется."
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "Наклон скошенных краев на всех рамках портретов и индикаторах заклинаний. 21% — обычный вид."
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "Насколько далеко расходится тень вкладки имени. 0 — без тени."
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "Насколько далеко числа разлетаются в стороны. При 0 они летят прямо вверх, как в игре."
L["How far the panel reaches past the buttons on every side."] = "Насколько панель выступает за кнопки с каждой стороны."
L["How far the soft shadow around DaylightUI's frames and windows reaches."] = "Насколько далеко расходится мягкая тень вокруг рамок и окон DaylightUI."
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "Насколько далеко расходится тень этой рамки. 0 — без тени."
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "Сколько уровня вы прошли, например 24%. Если числа тоже включены, стоит между ними и опытом отдыха."
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "Как записываются числа здоровья и ресурса на рамках портретов, дополнительных текстах и индикаторах здоровья. Проценты не меняются."
L["How long a line stays on screen before it fades away."] = "Как долго строка остается на экране, прежде чем исчезнуть."
L["How long a new item stays in Recent before it goes to its own group."] = "Как долго новый предмет остается в «Недавних», прежде чем перейти в свою группу."
L["How long each buff and debuff has left, on the top edge of its icon."] = "Оставшееся время каждого положительного и отрицательного эффекта, на верхнем краю его значка."
L["How long each line stays after your last loot of it."] = "Как долго каждая строка остается после последнего получения этой добычи."
L["How long it stays before fading, unless the buffs land first."] = "Как долго остается перед затуханием, если эффекты не будут применены раньше."
L["How low the enemy's health has to be."] = "Насколько низким должно быть здоровье противника."
L["How many bars sit on your screen. Each one can be changed on its own later."] = "Сколько панелей на экране. Каждую можно потом настроить отдельно."
L["How many buttons this bar shows."] = "Сколько кнопок на этой панели."
L["How many data texts share the strip. Pick what each shows under Slots."] = "Сколько информационных текстов на полосе. Что показывает каждый, выберите в «Ячейках»."
L["How many of the newest messages per chat tab come back after /reload."] = "Сколько новейших сообщений каждой вкладки чата возвращается после /reload."
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "На сколько строк разбиваются кнопки (столбцов, если панель вертикальная)."
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "Сколько ячеек в каждой строке сумки. Больше столбцов — шире и ниже."
L["How many yards away it is."] = "Сколько до него метров."
L["How much a block, absorb or resist saved you."] = "Сколько урона предотвратил блок, поглощение или сопротивление."
L["How much color the empty part of a bar keeps."] = "Сколько цвета сохраняет пустая часть полосы."
L["How much of the health bar's width the row spans, centered."] = "Какую часть ширины шкалы здоровья занимает строка, по центру."
L["How much the shield can still soak, at the bar's right end."] = "Сколько еще может поглотить щит, у правого края полосы."
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "Сколько еще может поглотить щит, на значке вместо времени. Размер и цвет — как у чисел восстановления."
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "Как строки задач показывают прогресс: цветами ниже, зеленым после выполнения или переходом от красного к зеленому по мере заполнения."
L["How round the name tab's corners are. 0 keeps them sharp."] = "Насколько скруглены углы вкладки имени. 0 — острые углы."
L["How round this frame's corners are. 0 keeps them sharp."] = "Насколько скруглены углы этой рамки. 0 — острые углы."
L["How see-through a frame gets while its unit is out of range."] = "Насколько прозрачной становится рамка, пока ее цель вне зоны действия."
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "Насколько прозрачным становится заклинание с настройкой «Затухание», готовое или на восстановлении."
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "Насколько прозрачен значок заклинания во время восстановления. Общее время восстановления не учитывается."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "Насколько прозрачны все окна и панели: сумки, персонаж, книга заклинаний, окно NPC, поиск группы, переоформленные окна игры, а также чат, информационная панель, окно заданий и панели эффектов, если на их страницах не задана своя."
L["How see-through it is while shown, whatever the fade does."] = "Насколько прозрачен, пока виден, независимо от затухания."
L["How see-through it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "Насколько прозрачен, когда и насколько затухает. В режиме перемещения, тестовом режиме или при открытой этой странице виден со своей видимостью."
L["How see-through party and raid frames get while a member is out of range."] = "Насколько прозрачными становятся рамки группы и рейда, пока участник вне зоны действия."
L["How see-through the borders around DaylightUI's frames and windows are."] = "Насколько прозрачна кайма вокруг рамок и окон DaylightUI."
L["How see-through the info panel's boxes and the meters' own windows are."] = "Насколько прозрачны блоки информационной панели и отдельные окна счетчиков."
L["How see-through the other plates get while you have a target."] = "Насколько прозрачными становятся другие индикаторы, пока у вас есть цель."
L["How see-through the world map's symbols are. Lower it to see more of the map under them."] = "Насколько прозрачны символы на карте мира. Уменьшите, чтобы лучше видеть карту под ними."
L["How should it look?"] = "Как это должно выглядеть?"
L["How solid its background is: 0 is fully see-through."] = "Насколько плотный фон: 0 — полностью прозрачный."
L["How solid the ribbon behind each loot feed line is: 0 is fully see-through."] = "Насколько плотная лента за каждой строкой ленты добычи: 0 — полностью прозрачная."
L["How solid the dark background is."] = "Насколько плотный темный фон."
L["How strong the highlight on an active spell is."] = "Сила подсветки активного заклинания."
L["How strong the mouseover color over the icon is."] = "Сила цвета при наведении на значок."
L["How strong the pressed color over the icon is."] = "Сила цвета при нажатии на значок."
L["How strongly it lights up once the enemy is in range."] = "Насколько ярко подсвечивается, когда противник в зоне действия."
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "Насколько сильно цвет отрицательного эффекта окрашивает шкалу здоровья. Только для подсветки «Оттенок» или «Оба»."
L["How strongly the spell cost shows on your power bar."] = "Насколько заметна стоимость заклинания на шкале ресурса."
L["How tall a friendly plate's health bar is."] = "Высота шкалы здоровья индикатора союзника."
L["How tall each enemy plate's health bar is."] = "Высота шкалы здоровья каждого индикатора противника."
L["How tall each line of text over you is. The game's own is 25."] = "Высота каждой строки текста над вами. В игре — 25."
L["How tall each of the threat meter's bars is."] = "Высота каждой полосы счетчика угрозы."
L["How tall each of this meter's bars is."] = "Высота каждой полосы этого счетчика."
L["How tall each pet bar is."] = "Высота каждой полосы питомца."
L["How tall each raid tile is."] = "Высота каждой ячейки рейда."
L["How tall each swing timer bar is."] = "Высота каждой полосы таймера атаки."
L["How tall each tile's power bar is."] = "Высота шкалы ресурса каждой ячейки."
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height."] = "Высота шкалы здоровья всех остальных индикаторов, пока у вас есть цель, как доля «Высоты шкалы здоровья»."
L["How tall the cast bar under an enemy plate is."] = "Высота индикатора заклинаний под индикатором противника."
L["How tall the experience bar is."] = "Высота индикатора опыта."
L["How tall the health bar is."] = "Высота шкалы здоровья."
L["How tall the health bar under the tooltip is."] = "Высота шкалы здоровья под подсказкой."
L["How tall the meter's own window is."] = "Высота отдельного окна счетчика."
L["How tall the pets' power bars are."] = "Высота шкал ресурса питомцев."
L["How tall the power bar is."] = "Высота шкалы ресурса."
L["How tall the second meter's window is."] = "Высота окна второго счетчика."
L["How tall the tab holding the name above the frame is."] = "Высота вкладки с именем над рамкой."
L["How tall this frame is."] = "Высота этой рамки."
L["How tall your cast bar is."] = "Высота вашего индикатора заклинаний."
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Высота индикатора заклинаний фокуса. Не внутри рамки, где он занимает место шкалы ресурса."
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Высота индикатора заклинаний цели. Не внутри рамки, где он занимает место шкалы ресурса."
L["How tall your target's health bar is, as a share of Health bar height."] = "Высота шкалы здоровья цели как доля «Высоты шкалы здоровья»."
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "Как выглядит текст здоровья на индикаторах союзников: процент, само здоровье, здоровье из максимума, оба варианта или недостающее."
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "Как выглядит текст здоровья: процент, само здоровье, здоровье из максимума, оба варианта или недостающее."
L["How the pets' health text is written."] = "Как записывается текст здоровья питомцев."
L["How the power text is written."] = "Как записывается текст ресурса."
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "Как записывается текст здоровья на ячейках. «Недостающее» ничего не показывает, пока здоровье участника полное."
L["How thick the border around each button is."] = "Толщина каймы вокруг каждой кнопки."
L["How thick the name tab's outline is. 0 leaves none."] = "Толщина контура вкладки имени. 0 — без контура."
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "Как обрамлены положительные эффекты этой категории: одним цветом или градиентом. Щелкните, чтобы изменить."
L["How this extra text writes the health."] = "Как этот дополнительный текст записывает здоровье."
L["How this extra text writes the power."] = "Как этот дополнительный текст записывает ресурс."
L["How wide a friendly plate's health bar is."] = "Ширина шкалы здоровья индикатора союзника."
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "Ширина каждого деления приемов серии. Не действует, пока деления подстраиваются под ширину рамки."
L["How wide each enemy plate's health bar is."] = "Ширина шкалы здоровья каждого индикатора противника."
L["How wide each pet bar is."] = "Ширина каждой полосы питомца."
L["How wide each raid tile is."] = "Ширина каждой ячейки рейда."
L["How wide every other plate is while you have a target, as a share of Width."] = "Ширина всех остальных индикаторов, пока у вас есть цель, как доля «Ширины»."
L["How wide the bars are."] = "Ширина полос."
L["How wide the damage meter is, in the panel or in its own window."] = "Ширина счетчика урона, на панели или в отдельном окне."
L["How wide the list is."] = "Ширина списка."
L["How wide the name tab is when Name tab width is Fixed width."] = "Ширина вкладки имени, когда «Ширина вкладки имени» — «Фиксированная ширина»."
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "Ширина окна второго счетчика. Перетаскивание его угла в режиме перемещения тоже меняет ее."
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "Ширина отдельного индикатора опыта. Перетаскивание его угла в режиме перемещения тоже меняет ее."
L["How wide the threat meter is."] = "Ширина счетчика угрозы."
L["How wide this frame is."] = "Ширина этой рамки."
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Ширина индикатора заклинаний фокуса. Не внутри рамки и не пока он подстраивается под ширину рамки."
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Ширина индикатора заклинаний цели. Не внутри рамки и не пока он подстраивается под ширину рамки."
L["How wide your target's plate is, as a share of Width."] = "Ширина индикатора цели как доля «Ширины»."
L["How you find your way to quests, and how they show in the tracker."] = "Как вы находите путь к заданиям и как они выглядят в списке заданий."
L["How your target's plate stands out from the rest."] = "Как индикатор цели выделяется среди остальных."
L["Hunter"] = "Охотник"
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "Для охотников: линия на полосе дальнего боя, где начинается подготовка Автоматической стрельбы, с учетом скорости и задержки. Движение после нее задерживает выстрел, поэтому полоса остается полной и пишет «Остановитесь», пока вы не встанете."
L["I'd like to train."] = "Я хочу поучиться."
L["INTERRUPTS"] = "Прерывание"
L["Icon"] = "Значок"
L["Icon (the game's)"] = "Значок (игровой)"
L["Icon look"] = "Вид значка"
L["Icon per class"] = "Значок для каждого класса"
L["Icon positions and sizes"] = "Положение и размер значков"
L["Icon size"] = "Размер значков"
L["Icon style"] = "Стиль значков"
L["Icon zoom"] = "Приближение значков"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "Значки заполняют панель от правого края влево, к центру экрана."
L["Icons left / right"] = "Значки влево / вправо"
L["Icons on a row before it wraps to the next."] = "Значков в строке до переноса на следующую."
L["Icons on bars"] = "Значки на полосах"
L["Icons per row"] = "Значков в строке"
L["Icons up / down"] = "Значки вверх / вниз"
L["Idle time (seconds)"] = "Время бездействия (сек.)"
L["Ignore"] = "Черный список"
L["Ignored"] = "Игнорируются"
L["Import"] = "Импорт"
L["Import profile"] = "Импорт профиля"
L["Imported the profile %s."] = "Профиль %s импортирован."
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "В группе или с питомцем — маленькая метка в верхнем внутреннем углу рамки: ваша угроза по цели, где 100% значит, что она переключится на вас. Оранжевая при приближении, красная, когда цель уже на вас."
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "В группе окрашивает существо в зависимости от того, кого оно атакует; в одиночку индикаторы не меняются. Для танка: красный, когда оно атакует другого, оранжевый, когда вы вот-вот его упустите, обычный, пока вы его держите. Для бойца или лекаря: оранжевый, когда вы близки к тому, чтобы его перетянуть, красный, когда оно атакует вас."
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "В группе или с питомцем кольцо цели (и метка угрозы) окрашивается в этот цвет, когда вы близки к тому, чтобы ее перетянуть."
L["In a raid, only the leader and assists can use the leader tools."] = "В рейде инструментами лидера могут пользоваться только лидер и помощники."
L["In a row above the bar."] = "В ряд над полосой."
L["In categories"] = "По категориям"
L["In columns"] = "По столбцам"
L["In combat"] = "В бою"
L["In combat in a group or with a pet"] = "В бою в группе или с питомцем"
L["In combat, when I'm the tank"] = "В бою, когда я танк"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "В подземельях, рейдах, на полях боя и аренах все, что настроено на затухание, остается видимым, как при затухании «Никогда». Снова затухает, когда вы выйдете наружу."
L["In fights"] = "В бою"
L["In fights and when idle"] = "В бою и при бездействии"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "В бою: панель и вкладки уплывают, а сообщения остаются поверх мира. При бездействии: весь чат тоже затухает, если некоторое время ничего нового не приходит. Всегда: во время игры нет панели и вкладок, только сообщения. Наведение курсора на чат или нажатие Enter возвращает его."
L["In progress"] = "Выполняется"
L["In rows"] = "По строкам"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "В пикселях экрана, чтобы оставаться четким при любом масштабе интерфейса. Для толстой каймы нужно 3 или больше."
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "В поле ввода чата стрелки вверх и вниз листают отправленное. Alt+вверх и Alt+вниз работают как раньше. Пока поле открыто, стрелки не поворачивают персонажа."
L["In the group"] = "В группе"
L["In the info panel"] = "На информационной панели"
L["In use"] = "Используется"
L["In use: %s"] = "Используется: %s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "В акцентном цвете (раздел «Внешность»), меняется вместе с ним. Если выключено, используется цвет ниже."
L["In your layout: click to pick it."] = "В вашем макете: щелкните, чтобы выбрать."
L["Inactive"] = "Неактивен"
L["Inbox"] = "Входящие сообщения"
L["Incoming heals"] = "Входящее исцеление"
L["Info"] = "Справка"
L["Info Panel"] = "Информационная панель"
L["Info panel"] = "Информационная панель"
L["Info panel background opacity"] = "Прозрачность фона информационной панели"
L["Inner end"] = "Внутренний край"
L["Inside the frame"] = "Внутри рамки"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "Внутри рамки он закрывает шкалу ресурса и имеет ту же ширину (в стиле «Лента» вместо этого располагается под рамкой). Сверху, снизу или отдельно это полоса, размер которой задается здесь; отдельную перемещайте в режиме перемещения."
L["Inspect"] = "Осмотреть"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "Осмотр игрока открывает окно DaylightUI с его экипировкой и талантами. Выключите, чтобы использовать окно игры."
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "Установите модификацию Jiberish Fabled Icons, чтобы открыть больше стилей значков классов."
L["Instance"] = "Подземелье"
