L["It shows when the first meter would: the Damage meter page's \"Show only in a group\" and \"Show only in combat\" count for both. Reset clears the fights in both."] = "Он появляется, когда появился бы первый счетчик: «Показывать только в группе» и «Показывать только в бою» на странице счетчика урона действуют на оба. Сброс очищает бои в обоих."
L["It slides back once the fight ends. A click on its tab overrides this until the next fight starts or ends."] = "Возвращается, когда бой заканчивается. Щелчок по его вкладке отменяет это до начала или конца следующего боя."
L["It takes a reload."] = "Требуется перезагрузка."
L["It's %s. Just one more quest?"] = "Уже %s. Еще одно задание?"
L["Item"] = "Предмет"
L["Item ID"] = "ID предмета"
L["Item buttons"] = "Кнопки предметов"
L["Item icons"] = "Значки предметов"
L["Item level"] = "Уровень предметов"
L["Item level %s"] = "Уровень предмета %s"
L["Item level line"] = "Строка уровня предмета"
L["Item names beside icons"] = "Названия предметов рядом со значками"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "Названия предметов в цвете их качества или все белым. Край значка сохраняет цвет качества."
L["Item quality border"] = "Кайма качества предмета"
L["Items"] = "Предметы"
L["Items and loot"] = "Предметы и добыча"
L["Items below this quality don't show, like gray junk."] = "Предметы ниже этого качества не показываются, например серый хлам."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "Предметы, разложенные по группам по типу. Чтобы переместить предмет в другую группу, перетащите его на заголовок группы или щелкните по нему правой кнопкой мыши с Alt. Щелкните по заголовку, чтобы свернуть его. Alt + правый щелчок также блокирует предмет, чтобы он никогда не продавался и не распылялся."
L["Items that are uncommon or better get a border in their quality color."] = "Предметы необычного качества и выше получают кайму в цвете своего качества."
L["Items you loot, create, buy or get from a quest."] = "Предметы, которые вы добываете, создаете, покупаете или получаете за задания."
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "Предметы, которые ваш класс, уровень или навыки пока не позволяют использовать, или которые вы уже знаете, получают красный значок, как у торговца."
L["Itim"] = "Itim"
L["Its buff or debuff"] = "Его эффект"
L["Its cooldown"] = "Его восстановление"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "Его окна настроек и «My Journey», а также значки задач заданий на картах, каждое задание своим цветом."
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "Собственное затухание, отдельно от панели. При открытой странице показывает пример группы."
L["Its own window"] = "Отдельное окно"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Отдельное окно, сначала в правом нижнем углу. Перемещайте его в режиме перемещения (/dui unlock) и тяните за угол, чтобы изменить размер."
L["Its owner's class"] = "Класс владельца"
L["Its owner's class tells at a glance whose pet it is."] = "Класс владельца сразу показывает, чей это питомец."
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "Его полосы таймеров с вашим шрифтом, текстурой полос и каймой. Размеры, цвета и места остаются как в DBM."
L["BigWigs and LittleWigs"] = "BigWigs и LittleWigs"
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "Их полосы таймеров с вашим шрифтом, текстурой полосы и рамкой, на стиле полос Default в BigWigs. Размеры, цвета и расположение остаются от BigWigs."
L["Its window, and each attunement chain drawn like the talent trees."] = "Его окно, а каждая цепочка допуска нарисована как деревья талантов."
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "Jiberish Fabled Icons установлен. Выберите значок для каждого класса ниже: любой стиль или одну из его специализаций. Первый значок в каждой строке следует «Стилю значков»."
L["Join a group to use the leader tools, or try them with /dui leader test."] = "Вступите в группу, чтобы пользоваться инструментами лидера, или опробуйте их командой /dui leader test."
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "Присоединяйтесь к Discord DaylightUI: нажмите Ctrl+C, чтобы скопировать ссылку, и вставьте ее в браузер."
L["Junk"] = "хлам"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Сразу слева от панели, вровень с ее верхом, и следует за ней при изменении размера мини-карты или счетчика урона. Выключите, чтобы перемещать панель самостоятельно в режиме перемещения."
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Сразу слева от панели, первый ряд опирается на ее нижний край, и следует за ней при изменении размера мини-карты или счетчика урона. Выключите, чтобы перемещать панель самостоятельно в режиме перемещения."
L["Just this spell, for now"] = "Пока только это заклинание"
