L["Keybinds"] = "Назначенные клавиши"
L["Keybinds, stack counts, macro names and cooldown numbers on every bar, the Cooldown Manager and totems. General uses the font on General > Appearance."] = "Клавиши, число стаков, названия макросов и числа восстановления на всех панелях, в трекере восстановления и на тотемах. «Общий» использует шрифт из раздела «Общий > Внешность»."
L["Keys"] = "Клавиши"
L["Kicked by"] = "Прервал"
L["Kinds: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nBinding: boe, bou, soulbound. In an equipment set: set, or the set's name. Locked: locked\nQuality: poor, common, uncommon, rare, epic, legendary, or q>rare, q>=uncommon, q<epic\nItem level: ilvl>20, ilvl<=10, ilvl20-30\nJoin with & (all) or | (any), ! for not: boe & q>common, food | potion, gear & !set\nA word that isn't one of these finds names. Start with # for the keyword only."] = "Виды: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nПривязка: boe, bou, soulbound. В комплекте экипировки: set или название комплекта. Заблокированные: locked\nКачество: poor, common, uncommon, rare, epic, legendary, или q>rare, q>=uncommon, q<epic\nУровень предмета: ilvl>20, ilvl<=10, ilvl20-30\nОбъединяйте через & (все) или | (любое), ! — отрицание: boe & q>common, food | potion, gear & !set\nДругое слово ищет по названиям. Начните с #, чтобы искать только по ключевому слову."
