L["Loot, money, XP, reputation and skill-ups don't bring the chat back, so it stays out of the way while you grind. Whispers, party, guild and other messages still do."] = "Добыча, деньги, опыт, репутация и повышение навыков не возвращают чат, чтобы он не мешал при фарме. Шепот, группа, гильдия и другие сообщения по-прежнему возвращают."
L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "Объекты заданий, которые можно обыскать, мерцают, как и те, кто дает задания (в игре нет отдельной настройки для одного из них). Игра показывает мерцание, только если контур вокруг того, на что вы указываете, выключен, поэтому этот контур остается выключенным. Если выключить эту настройку, контур вернется; мерцание может остаться до перезапуска игры."
L["Low health and mana warning"] = "Предупреждение о нехватке здоровья и маны"
L["Lowers the arcane damage you take, and how often arcane spells hit you in full."] = "Снижает получаемый урон от тайной магии и то, как часто заклинания тайной магии поражают вас в полную силу."
L["Lowers the fire damage you take, and how often fire spells hit you in full."] = "Снижает получаемый урон от огня и то, как часто заклинания огня поражают вас в полную силу."
L["Lowers the frost damage you take, and how often frost spells hit you in full."] = "Снижает получаемый урон от магии льда и то, как часто заклинания льда поражают вас в полную силу."
