L["Nudges the icons up or down from their position."] = "Сдвигает значки вверх или вниз."
L["Nudges the level badge sideways. Not while it sits on the portrait."] = "Сдвигает значок уровня влево или вправо. Не когда он на портрете."
L["Nudges the level badge up or down. Not while it sits on the portrait."] = "Сдвигает значок уровня вверх или вниз. Не когда он на портрете."
L["Nudges the name sideways from its position."] = "Сдвигает имя влево или вправо."
L["Nudges the name tab sideways along the frame's top."] = "Сдвигает вкладку имени вдоль верхнего края рамки."
L["Nudges the name up or down from its position."] = "Сдвигает имя вверх или вниз."
L["Nudges the pet bars sideways from their position."] = "Сдвигает полосы питомцев влево или вправо."
L["Nudges the pet bars up or down from their position."] = "Сдвигает полосы питомцев вверх или вниз."
L["Nudges the power text sideways from its place."] = "Сдвигает текст ресурса влево или вправо."
L["Nudges the power text up or down from its place."] = "Сдвигает текст ресурса вверх или вниз."
L["Nudges the row of pips sideways."] = "Сдвигает ряд делений влево или вправо."
L["Nudges the row of pips up or down."] = "Сдвигает ряд делений вверх или вниз."
L["Nudges this extra text sideways from its position."] = "Сдвигает этот доп. текст влево или вправо."
L["Nudges this extra text up or down from its position."] = "Сдвигает этот доп. текст вверх или вниз."
L["Nudges this square sideways from its position."] = "Сдвигает этот квадрат влево или вправо."
L["Nudges this square up or down from its position."] = "Сдвигает этот квадрат вверх или вниз."
L["Nudges this text away from its spot on the button, in pixels."] = "Сдвигает этот текст от его места на кнопке, в пикселях."
L["Number of data texts"] = "Число инфотекстов"
L["Numbered channels keep their number with the short tag: [1. G] for General, [2. T] for Trade."] = "Нумерованные каналы сохраняют номер в коротком теге: [1. G] для «Общего», [2. T] для «Торговли»."
