L["OFFLINE"] = "НЕ В СЕТИ"
L["OK"] = "ОК"
L["OVERALL"] = "ОБЩИЙ"
L["Objective color"] = "Цвет задачи"
L["Objective progress color"] = "Цвет прогресса задачи"
