L["Objectives"] = "Задачи"
L["Objectives, counts, hand-in lines and timers."] = "Задачи, счетчики, строки сдачи и таймеры."
L["Octagon"] = "Восьмиугольник"
L["Off"] = "Откл."
L["Off Hand"] = "Левая рука"
