L["Old layout: %s, set %d"] = "Старый макет: %s, набор %d"
L["On a flight path, a bar at the top of the screen shows where you're going and the time left. Each route's time is learned the first time you fly it, for all your characters. Move it with /dui unlock."] = "Во время полета полоса вверху экрана показывает, куда вы летите и сколько осталось. Время каждого маршрута запоминается при первом полете, для всех ваших персонажей. Переместить: /dui unlock."
L["On a ready check, and when you enter a dungeon or raid in a group, a short line shows the group buffs you don't have yet: only ones someone in your group can give. It fades once they land. Move it in unlock mode."] = "При проверке готовности и при входе в подземелье или рейд в группе короткая строка показывает групповые эффекты, которых у вас еще нет: только те, что может дать кто-то из группы. Она угасает, когда они получены. Перемещается в режиме открепления."
L["On cooldown"] = "Не готов"
L["On in the Healer setup. Each class has its own picks; change them below."] = "Включено в настройке «Лекарь». У каждого класса свой выбор; измените его ниже."
L["On its own (unlock to move)"] = "Отдельно (открепите, чтобы переместить)"
L["On its own, the power bar leaves the frame and you can move it anywhere in unlock mode, like the middle of the screen. The frame is then all health."] = "Отдельно шкала ресурса покидает рамку, и ее можно переместить куда угодно в режиме открепления, например в центр экрана. Тогда вся рамка отдана здоровью."
L["On the plate"] = "На индикаторе"
L["On the portrait"] = "На портрете"
L["On the portrait rings of the player, target and focus frames."] = "На кольцах портретов рамок игрока, цели и фокуса."
L["One click sets where the auras and the name sit. Change anything after."] = "Один щелчок расставляет ауры и имя. Потом можно изменить что угодно."
L["One color"] = "Один цвет"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "Один цвет на всех делениях; переход от цвета приема серии к полному цвету вдоль ряда; цвет вашего класса; или пары цветов со страницы «Градиенты» (приемы серии), одна на все деления или своя на каждое. Приемы серии на индикаторах здоровья используют те же цвета."
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Один свой цвет, цвет вашего класса или два цвета вашего класса градиентом (со страницы «Градиенты»)."
L["One gradient (Gradients page)"] = "Один градиент (страница «Градиенты»)"
L["One more thing at the end of the same line, after the second part."] = "Еще одно в конце той же строки, после второй части."
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "По строке на каждого участника группы и питомца в списке угрозы вашей цели, сначала наибольшая, вы всегда в нем. Процент считается до срыва: на 100% цель переключится на вас."
L["One switch per part of the game's windows."] = "По переключателю на каждую часть окон игры."
L["One tile with the count"] = "Одна ячейка со счетчиком"
L["One tile: each section of the bank shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Одна ячейка: каждый раздел банка показывает одну пустую ячейку с числом свободных. Перетащите на нее предмет, чтобы положить его туда."
L["One tile: each section shows a single empty slot with the free count on it."] = "Одна ячейка: каждый раздел показывает одну пустую ячейку с числом свободных."
L["One tile: each section shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Одна ячейка: каждый раздел показывает одну пустую ячейку с числом свободных. Перетащите на нее предмет, чтобы положить его туда."
L["Ones that matter in a fight"] = "Важные в бою"
L["Online"] = "В сети"
L["Only at full health"] = "Только при полном здоровье"
L["Only clears this list. Moved buffs stay in their new categories."] = "Только очищает этот список. Перемещенные эффекты остаются в новых категориях."
L["Only debuffs I can dispel"] = "Только эффекты, которые я могу рассеять"
L["Only in a group"] = "Только в группе"
L["Only in combat"] = "Только в бою"
L["Only mine"] = "Только мои"
L["Only ones I can dispel"] = "Только те, что я могу рассеять"
L["Only spells you cast can be bound."] = "Назначить можно только заклинания, которые вы применяете."
L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "Над миром остаются только сообщения чата, каждое угасает через время, как плавающий чат (Чат > Плавающий). Остается, даже если включено «Скрывать все у костра»."
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "Только наложенные вами отрицательные эффекты или сначала ваши, а затем всех остальных."
L["Only under a minute"] = "Только меньше минуты"
L["Only when detached."] = "Только в отделенном виде."
L["Only when detached. Main hand at the bottom, the others above it."] = "Только в отделенном виде. Правая рука внизу, остальные над ней."
L["Only when detached. When attached, the bars match the cast bar's width."] = "Только в отделенном виде. В присоединенном полосы равны по ширине индикатору заклинаний."
L["Only when something changes"] = "Только при изменениях"
L["When not usable"] = "Когда нельзя использовать"
L["Only while the power bar is on its own."] = "Только когда шкала ресурса отдельно."
L["Only while the power bar is on its own. When off, both ends are straight."] = "Только когда шкала ресурса отдельно. Если выключено, оба края прямые."
L["Only with a target"] = "Только при наличии цели"
L["Only your group's leader can change the listing."] = "Изменить заявку может только лидер группы."
L["Only your group's leader can list the group."] = "Записать группу может только ее лидер."
L["Opacity"] = "Видимость"
L["Opacity & fade"] = "Видимость и угасание"
L["Opacity on cooldown"] = "Видимость при восстановлении"
L["Open DaylightUI options"] = "Открыть параметры DaylightUI"
L["Open a chat box first to link it."] = "Чтобы вставить ссылку, сначала откройте строку чата."
L["Open spot"] = "Свободное место"
L["Open stat groups"] = "Открытые группы характеристик"
L["Open this page at these settings."] = "Открыть эту страницу на этих параметрах."
L["Open world only"] = "Только в открытом мире"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "При открытии почтового ящика показывается окно DaylightUI: ваши письма, отправка и учет золота. Выключите, чтобы пользоваться окном игры. Учет ведется в любом случае."
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "При открытии профессии показывается окно DaylightUI: рецепты слева, выбранный справа. В бою открывается окно игры. Выключите, чтобы пользоваться окном игры."
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "При открытии торговца продается все из группы «Хлам»: серые предметы и все, что вы сами переместили в хлам. В чате видно, сколько вы получили."
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "При открытии торговца с ремонтом чинится все снаряжение, а в чате видна стоимость. Не в бою."
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and DaylightUI's own windows."] = "Открытие и закрытие окон: сумки, персонаж, книга заклинаний, журнал заданий, меню игры и окна DaylightUI."
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "При открытии поиска группы показывается окно DaylightUI: группы, к которым можно присоединиться, запись себя и кто рядом. В бою открывается окно игры. Выключите, чтобы пользоваться окном игры."
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "При открытии сумки неполные стопки одного предмета объединяются (15 и 5 льняной ткани становятся 20), чтобы не тратить ячейки. Не в бою, не во время обмена и не при открытом почтовом ящике или аукционе."
L["Opens the Gradients page, where the Combo points pairs are."] = "Открывает страницу «Градиенты», где находятся пары приемов серии."
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Открывает редактор макета прямо на экране: вытягивайте заклинания из лотка, перетаскивайте куда нужно, соединяйте их, щелкните, чтобы изменить. Откройте в любой момент командой /cdm. Только вне боя."
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "Открывает книгу заклинаний с включенным режимом «Заклинания: кнопки мыши»: щелкните по заклинанию нужной кнопкой мыши. Закончив, закройте книгу заклинаний, и эта страница вернется."
L["Option toggles"] = "Переключатели параметров"
L["Options"] = "Параметры"
L["Options (%s): %s"] = "Параметры (%s): %s"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "Окна параметров модификаций на Ace3, в настройках игры и в их собственных окнах: Questie, RestedXP и многие другие."
L["Or drag the badge in Design mode."] = "Или перетащите значок в режиме дизайна."
L["Orange timer when running out"] = "Оранжевый таймер под конец"
L["Orbitron"] = "Orbitron"
L["Oswald"] = "Oswald"
L["Other"] = "Другое"
L["Other addons"] = "Другие модификации"
L["Other addons' windows in DaylightUI style. One switch per addon you have installed."] = "Окна других модификаций в стиле DaylightUI. По переключателю на каждую установленную модификацию."
L["Other faction's flight masters"] = "Распорядители полетов другой фракции"
L["Other plates"] = "Другие индикаторы"
L["Other plates opacity"] = "Видимость других индикаторов"
