L["Others"] = "Остальные"
L["Daylight UI's journal, marker and arrow stay either way. You can change it later on the Quests options page."] = "Журнал, маркер и стрелка Daylight UI остаются в любом случае. Изменить можно позже на странице параметров «Задания»."
L["Our nameplates back."] = "Индикаторы здоровья Daylight UI возвращены."
L["Our nameplates hidden: check your FPS, then /dui platefps again."] = "Индикаторы здоровья Daylight UI скрыты: проверьте FPS, затем снова /dui platefps."
L["Out of a fight"] = "Вне боя"
L["Out of combat only"] = "Только вне боя"
