L["Outlines the member you have targeted, so you can find them at a glance."] = "Обводит участника, выбранного целью, чтобы его было видно с первого взгляда."
L["Outside spots may need more space between frames."] = "Внешним местам может понадобиться больше пространства между рамками."
L["Outside: above"] = "Снаружи: сверху"
L["Outside: below"] = "Снаружи: снизу"
L["Outside: bottom left"] = "Снаружи: снизу слева"
L["Outside: bottom right"] = "Снаружи: снизу справа"
L["Outside: left"] = "Снаружи: слева"
