L["Outside: top right"] = "Снаружи: сверху справа"
L["Over an hour away. Still here, still waiting."] = "Вас нет больше часа. Все еще здесь, все еще ждем."
L["Over its owner"] = "Над владельцем"
L["Over or under the frame, the buffs sit nearest it when both share a spot. Outside spots may need room around the frame."] = "Над или под рамкой положительные эффекты ближе к ней, если делят место. Внешним местам может понадобиться пространство вокруг рамки."
L["Over, under or beside the health bar. In Design mode on the preview, drag it there."] = "Над, под или рядом со шкалой здоровья. В режиме дизайна перетащите туда на предпросмотре."
L["Over, under or beside the health bar. Rows sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Над, под или рядом со шкалой здоровья. Ряды на одном месте выстраиваются наружу от шкалы. В режиме дизайна перетащите туда на предпросмотре."
L["Over, under, beside or on a friendly plate's health bar. Without the health bar the name stays centered."] = "Над, под, рядом или на шкале здоровья индикатора союзника. Без шкалы здоровья имя остается по центру."
L["Over, under, beside or on the health bar. Pieces sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Над, под, рядом или на шкале здоровья. Элементы на одном месте выстраиваются наружу от шкалы. В режиме дизайна перетащите туда на предпросмотре."
