L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "Нажмите 1–9, чтобы выбрать строку или награду, Пробел для следующего шага (принять, продолжить, завершить), Escape, чтобы выйти. Пробел не прыгает, пока вы в разговоре. Остальные клавиши по-прежнему работают в игре, а в бою все клавиши принадлежат игре."
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "Нажмите «Назначить в книге заклинаний» (или откройте %s и включите «Заклинания: кнопки мыши» вверху), затем щелкните по заклинанию нужной кнопкой мыши (с Shift, Ctrl или Alt — еще варианты). Такой щелчок по любой вашей рамке применит заклинание к этому существу. Закончив, закройте книгу заклинаний: эта страница вернется. Левая кнопка по-прежнему выбирает цель, а правая открывает меню, если их не назначить."
