L["Show your bag slots: drag a bag out, or drop one in."] = "Показать ячейки сумок: вытащите сумку или положите новую."
L["Show your cast bar"] = "Показывать свой индикатор заклинаний"
L["Show yourself"] = "Показывать себя"
L["Shown"] = "Показано"
L["Shows a grid while frames are unlocked, and snaps them to it."] = "Показывает сетку, пока рамки откреплены, и привязывает их к ней."
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "Показывает маркер на каждой рамке. Перетащите, чтобы переместить; правый щелчок по маркеру сбрасывает рамку."
L["Shows a macro's name on its button. When off, macros show their icon only."] = "Показывает название макроса на кнопке. Если выключено, у макросов только значок."
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "Показывает образец только этой рамки во время правки и каждое изменение сразу. Остается при смене страниц, пока вы его не выключите; бой его завершает."
L["Shows a sample of the line where it sits."] = "Показывает образец строки на ее месте."
L["Shows buffs icons on each member."] = "Показывает значки положительных эффектов на каждом участнике."
L["Shows crowd control icons on each member."] = "Показывает значки контроля на каждом участнике."
L["Shows debuffs icons on each member."] = "Показывает значки отрицательных эффектов на каждом участнике."
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "Показывает клавишу каждой кнопки на ней. Если выключено, клавиши работают, их просто не видно."
L["Shows each pet's health as text."] = "Показывает здоровье каждого питомца текстом."
L["Shows each pet's name."] = "Показывает имя каждого питомца."
L["Shows only while the buff is up, like Power Word: Shield."] = "Показывается только пока действует эффект, например «Слово силы: Щит»."
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "Показывает или скрывает ряд кнопок сумок. Клавиши сумок открывают их и при скрытом ряде."
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "Показывает или скрывает ряд маленьких кнопок, открывающих окна персонажа, книги заклинаний, талантов и другие. Их клавиши работают и при скрытом ряде."
L["Shows server time instead of your local time."] = "Показывает серверное время вместо местного."
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "Показывает цель, фокус, питомца, цель выбранной цели и группу на образцах, а также оба индикатора заклинаний во время применения, чтобы их можно было настроить и переместить без настоящей цели. Завершается с началом боя."
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "Показывает экран отсутствия сейчас. Щелкните или нажмите любую клавишу, чтобы закрыть. Также /dui afk."
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "Показывает кнопки календаря и отслеживания на правом краю карты, пока курсор над картой."
L["Shows the game's countdown on buttons that are on cooldown."] = "Показывает игровой отсчет на кнопках, которые восстанавливаются."
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "Показывает игровую маленькую золотую монету на серых предметах в банке, как в стандартных сумках."
L["Shows the game's small gold coin on gray items, like the default bags."] = "Показывает игровую маленькую золотую монету на серых предметах, как в стандартных сумках."
L["Shows the healer's name next to a heal on you."] = "Показывает имя лекаря рядом с исцелением на вас."
L["Shows the health text large and white in the frame's inner corner (in Ribbon, at the inner end of the row above the bar)."] = "Показывает текст здоровья крупно и белым во внутреннем углу рамки (в «Ленте» — у внутреннего края строки над шкалой)."
L["Shows the unit's name on this frame."] = "Показывает имя существа на этой рамке."
L["Shows these raid frames in a party too, in place of the party frames."] = "Показывает эти рамки рейда и в группе, вместо рамок группы."
L["Shows this square on each member while its spell is on them."] = "Показывает этот квадрат на каждом участнике, пока на нем действует заклинание."
L["Shows where the range is before the enemy gets there, faintly."] = "Слабо показывает границу дальности, прежде чем противник до нее дойдет."
L["Shrink icon when pressed"] = "Уменьшать значок при нажатии"
L["Side"] = "Сторона"
L["Silk"] = "Шелк"
L["Silver"] = "Серебро"
L["Simple Wood"] = "Простое дерево"
L["Since %s"] = "С %s"
L["Since you logged in"] = "С момента входа"
L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Sound)."] = "У костра экран согревается светом огня и искрами, слышится мягкий треск, а панели команд и рамки угасают. Двиньтесь, выберите цель или примените заклинание, и все вернется; бой возвращает все мгновенно. Звуки следуют параметру «Мягкие звуки интерфейса» (Общие > Звук)."
L["Size"] = "Размер"
L["Size as a percent of the button's normal size."] = "Размер в процентах от обычного размера кнопки."
L["Size of every plate, friendly and enemy. Plates keep this size at any distance."] = "Размер всех индикаторов, союзных и вражеских. Индикаторы сохраняют этот размер на любом расстоянии."
L["Size of the names and numbers on this meter's bars."] = "Размер имен и цифр на полосах этого счетчика."
L["Size of the names and percents on the threat meter."] = "Размер имен и процентов на счетчике угрозы."
L["Size of the numbers on the experience bar."] = "Размер цифр на индикаторе опыта."
L["Size target separately"] = "Отдельный размер для цели"
L["Sizing"] = "Размеры"
