L["Skull when your DoTs will kill it"] = "Череп, когда ваши периодические эффекты добьют цель"
L["Skull, cross and the rest, on the tile of a marked member."] = "Череп, крест и другие на ячейке помеченного участника."
L["Skull, cross and the rest, shown in the name tab before the name."] = "Череп, крест и другие на вкладке имени перед именем."
L["Slant"] = "Наклон"
L["Slant angle"] = "Угол наклона"
L["Slide icons in and out"] = "Значки выезжают и уезжают"
