L["Slide over when a buff drops"] = "Сдвигать, когда эффект пропадает"
L["Slim bar"] = "Тонкая полоса"
L["Slot"] = "Ячейка"
L["Slot size"] = "Размер ячейки"
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for Bank and alts alone: their rows show below."] = "Размер ячеек, отступы, масштаб, расстановка предметов, пустые ячейки и метки на значках следуют странице «Сумки». Выключите, чтобы задать их отдельно для «Банка и альтов»: строки появятся ниже."
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "Размер ячеек, отступы, масштаб, расстановка предметов, пустые ячейки и метки на значках следуют странице «Сумки». Выключите, чтобы задать их отдельно для банка: строки появятся ниже."
L["Slots"] = "Ячейки"
L["Slots per row in the Bank and alts window."] = "Ячеек в ряду в окне «Банк и альты»."
L["Slots per row in the bank. It holds more than your bags, so it's wider by default."] = "Ячеек в ряду в банке. Он вмещает больше сумок, поэтому по умолчанию шире."
L["Slots with nothing on them show as empty frames. When off, they disappear and show again while you drag a spell or item."] = "Пустые ячейки показываются пустыми рамками. Если выключено, они исчезают и появляются снова, пока вы перетаскиваете заклинание или предмет."
L["Small Brown Pouch"] = "Маленький коричневый мешочек"
L["Small colored squares on each member for your heals over time and shields, like Renew or Power Word: Shield. Each square shows while your spell is on them."] = "Маленькие цветные квадраты на каждом участнике для ваших периодических исцелений и щитов, например «Обновление» или «Слово силы: Щит». Каждый квадрат виден, пока на участнике действует ваше заклинание."
L["Small helpers and the game's windows in DaylightUI style."] = "Мелкие помощники и окна игры в стиле DaylightUI."
L["Small helpers for looting, quests, trainers and more."] = "Мелкие помощники для добычи, заданий, учителей и не только."
L["Small helpers that save time every day. Each one says what it does."] = "Мелкие помощники, которые каждый день экономят время. У каждого написано, что он делает."
L["Small helpers: faster looting, quest automation, trainers and more."] = "Мелкие помощники: быстрая добыча, автоматизация заданий, учителя и не только."
L["Small icons in their own row, under the frame by default."] = "Маленькие значки в отдельном ряду, по умолчанию под рамкой."
L["Small icons over your frame, nearest it. Off by default: your buff bars show them too."] = "Маленькие значки над вашей рамкой, ближе всего к ней. По умолчанию выключено: их показывают и панели эффектов."
L["Small tiles for a raid of up to 10: one column per group, left to right. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "Маленькие ячейки для рейда до 10 человек: по столбцу на группу, слева направо. Показ, угасание, текстуры и шрифты отсюда действуют для всех размеров рейда; у группы своя страница."
L["Smooth bars"] = "Плавные полосы"
