L["Some boss abilities put debuffs on you that addons can't see. The game draws them itself, in a row under your debuffs."] = "Некоторые способности боссов накладывают на вас отрицательные эффекты, невидимые для модификаций. Игра рисует их сама, в ряду под вашими отрицательными эффектами."
