L["Stripes say \"shield\" at a glance. Plain is a flat fill; a shared-media bar uses that bar's look."] = "Полосы сразу показывают: «щит». Простой — ровная заливка; полоса из SharedMedia выглядит как эта полоса."
L["Stuns, fears, roots and the like: one big icon in the middle by default."] = "Оглушения, страх, обездвиживание и подобное: по умолчанию один большой значок в центре."
L["Style"] = "Стиль"
