L["Support DaylightUI on Ko-fi: press Ctrl+C to copy the link, then paste it in your browser."] = "Поддержите DaylightUI на Ko-fi: нажмите Ctrl+C, чтобы скопировать ссылку, затем вставьте ее в браузер."
L["Become a Daylight UI VIP on Patreon: press Ctrl+C to copy the link, then paste it in your browser."] = "Станьте VIP Daylight UI на Patreon: нажмите Ctrl+C, чтобы скопировать ссылку, затем вставьте ее в браузер."
L["Support on Ko-fi"] = "Поддержать на Ko-fi"
L["Survival"] = "Выживание"
L["Swaps the ends: light to dark instead of dark to light."] = "Меняет концы местами: от светлого к темному, а не от темного к светлому."
L["Swing Timer"] = "Таймер удара"
L["Swing timer"] = "Таймер удара"
L["Swing timer background"] = "Фон таймера удара"
L["Swing timer fill style"] = "Стиль заливки таймера удара"
L["Swing timer font"] = "Шрифт таймера удара"
L["Swing timer text size"] = "Размер текста таймера удара"
L["Swing timer texture"] = "Текстура таймера удара"
L["Swing timers"] = "Таймеры удара"
L["Switch between items grouped by kind and the plain bag-by-bag grid."] = "Переключение между предметами по категориям и простой сеткой по сумкам."
L["Switch between items grouped by kind and the plain tab-by-tab grid."] = "Переключение между предметами по категориям и простой сеткой по вкладкам."
L["Switch on, then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more): that click on a unit frame casts it. /dui > Unit Frames > Click-casting lists them."] = "Включите, затем щелкните по заклинанию нужной кнопкой мыши (удерживайте Shift, Ctrl или Alt для других сочетаний): такой щелчок по рамке применит его. Список: /dui > Рамки портретов > Заклинания: кнопки мыши."
L["Switch on, then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more): that click on a unit frame casts it. Closing the spellbook switches it off. /dui > Unit Frames > Click-casting lists them."] = "Включите, затем щелкните по заклинанию нужной кнопкой мыши (удерживайте Shift, Ctrl или Alt для других сочетаний): такой щелчок по рамке применит его. Закрытие книги заклинаний выключает режим. Список: /dui > Рамки портретов > Заклинания: кнопки мыши."
L["Switch to the profile %s?"] = "Перейти на профиль %s?"
L["Switches off: %s"] = "Будет отключено: %s"
L["Switches on: %s"] = "Будет включено: %s"
L["Switching a part on or off applies when you reload, at the end."] = "Включение или отключение части применяется при перезагрузке, в конце."
L["Switching an option on or off in /dui."] = "Включение или отключение параметра в /dui."
L["Switching profile after combat."] = "Смена профиля после боя."
L["System message color"] = "Цвет системных сообщений"
L["TAKEN"] = "ПОЛУЧЕНО"
L["THIS WEEK"] = "Неделя"
L["Tab by tab"] = "По вкладкам"
L["Tab underline"] = "Подчеркивание вкладки"
L["Tabard"] = "Гербовая накидка"
L["Taint: %d of the game's values are marked by DaylightUI (/dui taint for the list)."] = "Taint: DaylightUI пометил значений игры: %d (список: /dui taint)."
L["Taint: %d of the game's values are marked by DaylightUI:"] = "Taint: DaylightUI пометил значений игры: %d:"
L["Taint: %s"] = "Taint: %s"
L["Taint: nothing of the game's is marked by DaylightUI."] = "Taint: DaylightUI не пометил ничего из игры."
L["Take"] = "Взять"
L["Take gold out of the account bank."] = "Снять золото с банка учетной записи."
L["Takes effect once this fight is over."] = "Вступит в силу после окончания боя."
L["Takes the bar off the panel and puts it under your action bars. Move it in unlock mode; drag its corner to resize."] = "Убирает полосу с панели и ставит ее под панели команд. Перемещайте ее в режиме открепления; потяните за угол, чтобы изменить размер."
L["Takes the meter out of the panel into its own window in the bottom-right corner; move it in unlock mode."] = "Выносит счетчик из панели в отдельное окно в правом нижнем углу; перемещайте его в режиме открепления."
L["Takes the spell out of the layout; it goes back to the tray. Delete does too."] = "Убирает заклинание из раскладки; оно возвращается в лоток. Удаление делает то же самое."
L["Takes this extra aura group off the frame. Add another in Design mode."] = "Убирает эту дополнительную группу эффектов с рамки. Добавить другую можно в режиме дизайна."
L["Takes this extra text off the frame. Add another in Design mode."] = "Убирает этот дополнительный текст с рамки. Добавить другой можно в режиме дизайна."
L["Talent"] = "Талант"
L["Talent set"] = "Набор талантов"
