L["Talking to NPCs"] = "Разговор с НИП"
L["Talking to NPCs: gossip, quests to accept and hand in, rewards to choose, all in one window, in DaylightUI style."] = "Разговор с НИП: беседа, задания для взятия и сдачи, выбор наград — все в одном окне, в стиле DaylightUI."
L["Talking to an NPC opens DaylightUI's window for gossip, quests and rewards. Turn it off to use the game's own windows."] = "Разговор с НИП открывает окно DaylightUI для бесед, заданий и наград. Отключите, чтобы использовать окна игры."
L["Tall: 80 x 64, fill upward, buffs outside right"] = "Высокий: 80 x 64, заполнение вверх, эффекты справа снаружи"
L["Taller pips are easier to read at a glance."] = "Высокие деления легче прочесть с одного взгляда."
L["Tank"] = "Танк"
L["Tank, healer or damage, from the role they picked. Nothing shows for an unknown or unset role."] = "Танк, лекарь или боец — по выбранной роли. Если роль неизвестна или не выбрана, ничего не показывается."
L["Tapped"] = "Чужая добыча"
