L["Text size"] = "Размер текста"
L["Text size for every chat window. Set to 0 to keep each window's own size (set in its tab menu)."] = "Размер текста для всех окон чата. 0 — оставить каждому окну свой размер (задается в меню его вкладки)."
L["Text size in speech bubbles. Applies from the next bubble."] = "Размер текста в облачках. Применяется со следующего облачка."
L["Text size inside the frame"] = "Размер текста внутри рамки"
L["Text size of the count on a button, like charges or how many of an item you carry."] = "Размер счетчика на кнопке, например зарядов или числа предметов при себе."
L["Text size of the countdown on a button that's on cooldown."] = "Размер текста обратного отсчета на кнопке во время восстановления."
L["Text size of the key shown on each button."] = "Размер текста клавиши на каждой кнопке."
L["Text size of the macro names on buttons."] = "Размер текста названий макросов на кнопках."
L["Text size of the names on enemy plates."] = "Размер текста имен на индикаторах противников."
L["Text size of the names on friendly plates."] = "Размер текста имен на индикаторах союзников."
L["Text up / down"] = "Текст вверх / вниз"
L["Text: %s"] = "Текст: %s"
L["Thank you for making DaylightUI possible."] = "Спасибо, что делаете DaylightUI возможным."
L["Thank you to everyone who supports DaylightUI and keeps it growing."] = "Спасибо всем, кто поддерживает DaylightUI и помогает ему расти."
L["That border in the unit's class (or reaction) gradient from the Gradients page, running left to right."] = "Эта кайма в градиенте класса (или отношения) существа со страницы «Градиенты», слева направо."
L["That's as many builds as a set keeps: delete one first."] = "В наборе уже максимум сборок: сначала удалите одну."
L["The '?', the title and the hand-in line."] = "«?», название и строка сдачи."
L["The AFK screen can't show in combat, a boss fight, a keystone or a PvP match."] = "Экран отсутствия нельзя показать в бою, в битве с боссом, в эпохальном ключе или в PvP-матче."
L["The DaylightUI border, the item's quality color, your accent color (General > Appearance), or a color you pick."] = "Кайма DaylightUI, цвет качества предмета, ваш акцентный цвет (Общий > Внешность) или выбранный вами цвет."
L["The Fabled styles are art by JiberishUI and its artists, from the Jiberish Fabled Icons addon, read from its own folder. Without it installed, every style shows Daylight UI's own icons."] = "Стили Fabled — работы JiberishUI и ее художников, из модификации Jiberish Fabled Icons, берутся из ее собственной папки. Без нее все стили показывают значки Daylight UI."
L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "Кнопка «Наследие» открывает окно DaylightUI: сколько осталось до следующей награды, испытания и деревья наследия. Отключите, чтобы использовать окно игры."
L["The Mindless Ones completed."] = "Задание «Безмозглые» выполнено."
L["The NPC window is switched off (/dui > Talk)."] = "Окно НИП отключено (/dui > Разговор)."
L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "Заголовок «Задания» остается, даже когда ничего не отслеживается, чтобы было видно, где трекер."
L["The accent"] = "Акцентный цвет"
L["The aggro color when Aggro color is Custom color."] = "Цвет нападения, когда «Цвет нападения» — «Свой цвет»."
L["The arrow's color while Arrow color is set to Custom."] = "Цвет стрелки, когда «Цвет стрелки» — «Вручную»."
L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "Банк в том же виде, что и сумки. Группы и перемещенные предметы общие с сумками."
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "Полоса переходит от темного к светлому вместо одного ровного цвета. У репутации свой градиент на каждое отношение, его можно изменить на странице «Градиенты»."
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you."] = "Цвет полосы для мертвых и не в сети игроков, для чужих НИП и для НИП по их отношению к вам."
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "Цвет полосы, пока заклинание нельзя прервать, при любом стиле заливки."
L["The bar's color while the cast can't be interrupted."] = "Цвет полосы, пока заклинание нельзя прервать."
L["The bars over enemies' heads: how big they are, and what they show."] = "Полосы над головами противников: их размер и что они показывают."
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "Полосы переходят от темного к светлому вместо одного ровного цвета. Пары цветов — в Общий > Градиенты."
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "Полосы за концом здоровья для входящего исцеления и щитов поглощения. Сверхщит (щит больше недостающего здоровья) следует за щитом."
L["The bars' and names' colors on every unit frame."] = "Цвета полос и имен на всех рамках портретов."
L["The bars' color when Bar color is One color."] = "Цвет полос, когда «Цвет полосы» — «Один цвет»."
L["The border color of every loot feed line while Loot feed border color is set to Custom."] = "Цвет каймы каждой строки ленты добычи, когда «Цвет каймы ленты добычи» — «Вручную»."
L["The border color when Border color is set to Your own color."] = "Цвет каймы, когда «Цвет каймы» — «Ваш цвет»."
L["The border in the same color as the name."] = "Кайма того же цвета, что и имя."
L["The border of a debuff you can dispel, and the raid tile's dispel icon. Debuffs already on screen change after /reload."] = "Кайма отрицательного эффекта, который вы можете рассеять, и значок рассеивания на плитке рейда. Уже показанные эффекты изменятся после /reload."
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "Подложки за индикатором опыта, мини-картой и счетчиком урона, а также собственные окна счетчиков и счетчика угрозы. При видимости 0 подложки исчезают; мини-карта и полосы остаются."
L["The buffs wrap onto up to this many rows."] = "Положительные эффекты переносятся максимум на столько рядов."
L["The button's border lights up while the mouse is over it."] = "Кайма кнопки подсвечивается, пока над ней курсор."
L["The button's border lights up while you press it."] = "Кайма кнопки подсвечивается, пока вы ее нажимаете."
L["The cast bar's color when Fill style is One color."] = "Цвет индикатора заклинаний, когда «Стиль заливки» — «Один цвет»."
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "Окно персонажа и его вкладки (репутация, навыки, PvP, валюта, статистика), осмотр других игроков."
L["The chat menu, channel, voice and social buttons next to chat. When off, they're gone; their slash commands still work."] = "Кнопки меню чата, каналов, голоса и общения рядом с чатом. Если выключено, их нет; их команды чата по-прежнему работают."
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "Текст окна чата и облачка. «Общий» использует шрифт из Общий > Внешность."
L["The clock reads 18:30 instead of 6:30 PM."] = "Часы показывают 18:30 вместо 6:30 PM."
L["The color of a Curse debuff's border and dispel icon."] = "Цвет каймы и значка рассеивания для проклятия."
L["The color of a Disease debuff's border and dispel icon."] = "Цвет каймы и значка рассеивания для болезни."
L["The color of a Magic debuff's border and dispel icon."] = "Цвет каймы и значка рассеивания для магического эффекта."
L["The color of a Poison debuff's border and dispel icon."] = "Цвет каймы и значка рассеивания для яда."
L["The color of the glow around your target's bar."] = "Цвет свечения вокруг полосы вашей цели."
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "Цвет последнего деления или всего ряда при максимуме очков, а также конечный цвет для «Цвет до полного»."
L["The color of the names on the threat meter."] = "Цвет имен в счетчике угрозы."
L["The color of the names on this meter's bars."] = "Цвет имен на полосах этого счетчика."
L["The color of the outline around your target's bar."] = "Цвет контура вокруг полосы вашей цели."
L["The color of the pull line across the threat bars."] = "Цвет линии срыва агро на полосах угрозы."
L["The color of the shaded spell cost on your power bar."] = "Цвет затененной стоимости заклинания на полосе ресурса."
L["The color of the stretch for damage shields."] = "Цвет участка для щитов от урона."
L["The color of the stretch past the health for heals on their way."] = "Цвет участка за здоровьем для входящего исцеления."
L["The color the border lights up in while the mouse is over a button."] = "Цвет, которым подсвечивается кайма, пока курсор над кнопкой."
L["The color the border lights up in while you press a button."] = "Цвет, которым подсвечивается кайма, пока вы нажимаете кнопку."
L["The color the execute range lights up in."] = "Цвет подсветки зоны добивания."
L["The color used while the menu above is set to Custom."] = "Цвет, используемый, когда в меню выше выбрано «Вручную»."
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "Цветная развертка поверх значка, пока эффект действует. Если выключено, показывается только таймер."
L["The colors below"] = "Цвета ниже"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "Цвета, шрифт и текстуры, используемые везде. Экран меняется по мере выбора."
L["The cooldown edge's color when Cooldown edge is set to Your own color."] = "Цвет края восстановления, когда «Край восстановления» — «Ваш цвет»."
L["The cooldown layout can't be edited during combat."] = "Раскладку восстановлений нельзя менять в бою."
L["The cooldown manager's layout."] = "Раскладка трекера восстановления."
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "Значки отсчета для ваших тотемов над рамкой игрока. Перемещайте их в режиме открепления."
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "Отслеживаемые валюты (как их показывает список рюкзака игры) со значком и количеством, рядом с деньгами."
L["The dark part shrinks away instead of filling in."] = "Темная часть уменьшается, а не заполняется."
L["The dark ribbon behind each line. When off, only the icon and text show."] = "Темная лента за каждой строкой. Если выключено, показываются только значок и текст."
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "Информационные тексты, а также часы и частота кадров на мини-карте. «Общий» использует шрифт из Общий > Внешность."
L["The debuffs wrap onto up to this many rows."] = "Отрицательные эффекты переносятся максимум на столько рядов."
L["The dim line under each item's name. Repair warnings still show when it's off."] = "Тусклая строка под названием каждого предмета. Предупреждения о ремонте показываются и при выключенной."
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "Атлас подземелий, окна избранного и настроек; изображение каждого подземелья сохраняется."
L["The edge round each button. A proc still lights it up."] = "Кайма вокруг каждой кнопки. Срабатывание все равно ее подсвечивает."
L["The elite dragon wraps your own portrait too."] = "Дракон элиты обрамляет и ваш портрет."
L["The empty bar pulses while the buff is down."] = "Пустая полоса пульсирует, пока эффект не действует."
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "Пустая часть за заливкой каждой полосы, окрашенная в цвет полосы, кроме мест, где страница рамки выбирает другую."
L["The empty part behind the bars in DaylightUI's windows. General uses the bar background above."] = "Пустая часть за полосами в окнах DaylightUI. «Общий» использует фон полос выше."
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "Пустая часть каждой полосы в группе. Собственный фон заклинания (выше) важнее."
L["The empty part of every health bar: a dimmed copy of the bar's own color, or one you pick."] = "Пустая часть каждой полосы здоровья: затемненная копия цвета полосы или выбранный вами цвет."
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос трекера восстановления, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть индикатора заклинаний на каждом индикаторе здоровья, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть приемов серии на индикаторе здоровья цели, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть приемов серии, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос счетчиков урона, исцеления и угрозы, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полосы опыта и репутации, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полосы здоровья на каждом индикаторе здоровья, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полосы здоровья под подсказкой существа, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос здоровья питомцев, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос ресурса питомцев, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос прогресса в трекере и во всплывающем окне, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос здоровья плиток рейда, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полос ресурса плиток рейда, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть таймера удара, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полосы здоровья этой рамки, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть полосы ресурса этой рамки, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть вашего индикатора заклинаний, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть индикатора заклинаний фокуса, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "Пустая часть индикатора заклинаний цели, за заливкой. «Общий» использует фон полос из Общий > Внешность."
L["The empty part's color when Missing health color is Custom color."] = "Цвет пустой части, когда «Цвет недостающего здоровья» — «Свой цвет»."
L["The experience bar on top of the panel, or reputation at the level cap."] = "Индикатор опыта сверху панели или репутация на максимальном уровне."
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "Текст индикатора опыта и его +XP. «Общий» использует шрифт из Общий > Внешность."
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "Индикатор опыта, счетчик урона и мини-карта угасают вместе (и отдельное окно счетчика, если оно используется)."
L["The fifth chat channel you joined, often a custom one."] = "Пятый канал чата, к которому вы присоединились, часто созданный вручную."
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "Пятое деление заполняется полным цветом (сначала красным), чтобы полный ряд был заметен с одного взгляда."
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "Заливка всех полос: здоровье, ресурс, индикаторы заклинаний, таймеры удара, опыт, счетчик урона, индикаторы здоровья и другое, кроме мест, где страница рамки выбирает другую. Текстуры других модификаций (SharedMedia) идут после наших."
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "Заливка полос трекера восстановления. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the bars in DaylightUI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "Заливка полос в окнах DaylightUI: репутация, навыки, профессии, опыт питомца, задачи заданий. Они сохраняют скругленную форму. «Общий» использует текстуру полос выше."
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "Заливка индикатора заклинаний на каждом индикаторе здоровья. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "Заливка приемов серии на индикаторе здоровья цели. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "Заливка приемов серии. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "Заливка полос счетчиков урона, исцеления и угрозы. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "Заливка полосы опыта и репутации. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "Заливка полосы здоровья на каждом индикаторе здоровья. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "Заливка полосы здоровья под подсказкой существа. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "Заливка полос здоровья питомцев. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "Заливка полос ресурса питомцев. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "Заливка полос прогресса в трекере и во всплывающем окне. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "Заливка полос здоровья плиток рейда. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "Заливка полос ресурса плиток рейда. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "Заливка таймера удара. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "Заливка полосы здоровья этой рамки. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "Заливка полосы ресурса этой рамки. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "Заливка вашего индикатора заклинаний. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "Заливка индикатора заклинаний фокуса. «Общий» использует текстуру полос из Общий > Внешность."
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "Заливка индикатора заклинаний цели. «Общий» использует текстуру полос из Общий > Внешность."
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "Шрифт выше показывается везде сразу, кроме мест, где страница рамки или шрифт окон ниже выбирает другой. Эта кнопка возвращает их все к шрифту выше."
L["The friendly health bar's color when Bar color is One color."] = "Цвет полосы здоровья союзников, когда «Цвет полосы» — «Один цвет»."
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "Маркер над выбранным заданием и следы на земле к нему. С аддоном QuestieDB ещё и стрелка к ближайшей цели."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "Меню игры, список модификаций, макросы, часы, добыча, вставка камней, улучшение, утилизатор, аукционный дом, рамка карты мира, полоса дыхания."
L["The game only reports range for your group; anyone else stays at full opacity."] = "Игра сообщает дистанцию только для вашей группы; все остальные остаются полностью видимыми."
L["The game shows it as a bar."] = "Игра показывает это полосой."
L["The game shows it as an icon."] = "Игра показывает это значком."
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "Чат игры в стиле DaylightUI, в левом нижнем углу. Сам чат работает как обычно."
L["The game's new-player tips (the game setting 'Tutorials'). When off, they're turned off."] = "Советы игры для новичков (настройка игры «Обучение»). Если выключено, они отключаются."
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "Числа игры, вылетающие из того, кого вы бьете, и текст боя над вами."
L["The game's own"] = "Как в игре"
L["The game's own buff frames show beside DaylightUI's bars. When off, our bars replace them (they still show while Edit Mode is open)."] = "Окна эффектов игры показываются рядом с полосами DaylightUI. Если выключено, их заменяют полосы DaylightUI (они все равно показываются, пока открыт режим редактирования)."
L["The game's own messages: logins, /played, errors and the like."] = "Собственные сообщения игры: входы в игру, /played, ошибки и подобное."
L["The game's own setting: a quest you accept goes straight into the tracker."] = "Настройка игры: взятое задание сразу попадает в трекер."
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "Настройка игры: карта поворачивается вместе с вами, и направление взгляда всегда вверху. Если выключено, север всегда вверху."
L["The game's own settings for how the numbers leave the target."] = "Настройки игры для того, как числа разлетаются от цели."
L["The game's own switches."] = "Переключатели игры."
L["The game's own windows in DaylightUI style: the info panel's background, DaylightUI borders, font, controls and scroll bars."] = "Окна игры в стиле DaylightUI: фон инфопанели, кайма, шрифт, элементы управления и полосы прокрутки DaylightUI."
L["The game's own windows in the DaylightUI look."] = "Окна игры в стиле DaylightUI."
L["The game's quest tracker, placed under the panel."] = "Трекер заданий игры под панелью."
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "Текст боя игры над вашим персонажем: полученные удары, исцеление, срабатывания и другое."
L["The game's tooltips in the DaylightUI look."] = "Подсказки игры в стиле DaylightUI."
L["The game's tooltips."] = "Подсказки игры."
L["The gap between buff icons."] = "Промежуток между значками положительных эффектов."
L["The gap between combo point pips."] = "Промежуток между делениями приемов серии."
L["The gap between combo points."] = "Промежуток между приемами серии."
L["The gap between debuff icons."] = "Промежуток между значками отрицательных эффектов."
L["The gap between icons."] = "Промежуток между значками."
L["The gap between lines, when there's more than one."] = "Промежуток между строками, если их больше одной."
L["The gap between one party frame and the next."] = "Промежуток между рамками группы."
L["The gap between this bar's buttons."] = "Промежуток между кнопками этой панели."
L["The gap between this bar's icons."] = "Промежуток между значками этой полосы."
L["The glow behind your character in this color."] = "Свечение за вашим персонажем этого цвета."
L["The glowing border on a button when its spell procs."] = "Светящаяся кайма на кнопке при срабатывании ее заклинания."
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "Золото внизу сумки плавно отсчитывается до новой суммы. Требует «Эффекты движения» (Общий > Внешность)."
L["The green numbers over who you heal."] = "Зеленые числа над теми, кого вы исцеляете."
L["The guide that set this character up: a quick setup, a tour of everything DaylightUI does, or another profile."] = "Мастер, настроивший этого персонажа: быстрая настройка, обзор всего, что умеет DaylightUI, или другой профиль."
L["The guide window (old and new), its steps and its item and target boxes."] = "Окно гида (старое и новое), его шаги и окна предметов и целей."
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "Стрелка и время на каждой полосе. Под индикатором заклинаний текст уменьшается, чтобы поместиться на полосе."
L["The health and level numbers on the nameplates. General uses the font on General > Appearance."] = "Числа здоровья и уровня на индикаторах здоровья. «Общий» использует шрифт из Общий > Внешность."
L["The health bar fills bottom to top instead of across."] = "Полоса здоровья заполняется снизу вверх, а не поперек."
L["The health bar fills from the opposite side."] = "Полоса здоровья заполняется с противоположной стороны."
L["The health bar's color for a dead unit."] = "Цвет полосы здоровья мертвого существа."
L["The health bar's color for a friendly NPC."] = "Цвет полосы здоровья дружественного НИП."
L["The health bar's color for a player who went offline."] = "Цвет полосы здоровья игрока не в сети."
L["The health bar's color for an NPC someone else tagged first."] = "Цвет полосы здоровья НИП, которого первым атаковал кто-то другой."
L["The health bar's color for an NPC that attacks you."] = "Цвет полосы здоровья НИП, который нападает на вас."
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "Цвет полосы здоровья НИП, который не трогает вас, пока вы его не ударите."
L["The health bar's color when Health bar color is One color."] = "Цвет полосы здоровья, когда «Цвет индикатора здоровья» — «Один цвет»."
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "Текст здоровья показывается и при полном здоровье. Если выключено, он исчезает, пока здоровье полное."
L["The health text's color when Health text color is Custom."] = "Цвет текста здоровья, когда «Цвет текста здоровья» — «Вручную»."
L["The highest rank"] = "Высший ранг"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "Цвет выделения: спокойный тон Daylight, градиент Daylight, цвет вашего класса или его градиент (со страницы «Градиенты») или ваш собственный."
L["The highlight's color when Active spell is set to Your own color."] = "Цвет подсветки, когда «Активное заклинание» — «Ваш цвет»."
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "Значок задания, на которое указывает стрелка мини-карты (щелкните значок задания, чтобы выбрать его), и подсветка за значком под курсором."
L["The info panel, meter, map and tracker."] = "Инфопанель, счетчик, карта и трекер."
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain gray."] = "Уровень предметов внизу — в цвете качества вашей экипировки, прочность — от зеленого через желтый к красному. Если выключено, оба серые."
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "Уровень предметов для оружия и брони в банке, в левом нижнем углу."
L["The item level of weapons and armor in the bottom left corner."] = "Уровень предметов для оружия и брони, в левом нижнем углу."
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "Кобольды в шахте носят на головах свечи, чтобы видеть в темноте. Принеси мне восемь штук, и я не останусь в долгу."
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "Инструменты лидера отключены: Рамки портретов > Рейд > Инструменты лидера."
L["The leader tools open after the fight."] = "Инструменты лидера откроются после боя."
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "Инструменты лидера находятся рядом с рамками группы или рейда Daylight UI, а они отключены."
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "Корона лидера остается в бою. Если выключено, она скрывается, пока вы сражаетесь."
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "Линия под открытой вкладкой сверху (Персонаж, Репутация, Навыки...)."
L["The line under the open tab in this color."] = "Линия под открытой вкладкой этого цвета."
L["The line where the range starts. 0 hides it."] = "Линия, с которой начинается зона. 0 скрывает ее."
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "Строки в центре экрана (прервано, сумки полны, найдена новая местность) вашим шрифтом, ошибки — мягким красным, с плавным появлением и исчезновением. Перемещайте их через /dui unlock. Отключите, чтобы видеть красный и желтый текст игры."
L["The lines under the headers in this color."] = "Линии под заголовками этого цвета."
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "Список растет вверх от своей ручки, а не вниз. Для трекера, размещенного внизу экрана."
L["The look shared by everything DaylightUI draws."] = "Внешний вид, общий для всего, что рисует DaylightUI."
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "Окно браузера добычи, его списки, кнопки и диалоги; его значки и карты сохраняются."
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "Положение окна добычи хранит режим редактирования игры, а вы используете собственный макет режима редактирования: переместите его там (Esc > Редактировать)."
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "Низшие ранги каждого заклинания находятся под высшим, чтобы можно было применить старый ранг за меньшее количество маны. Если выключено, в книге заклинаний только высший ранг. На странице книги заклинаний есть такой же переключатель («Скрыть ранги»)."
L["The main hand bar's color."] = "Цвет полосы правой руки."
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the !."] = "Метка показывает, что требует задание, как на карте: меч — убить, сумка — добыть, шестеренка — использовать, глаз — исследовать, в цвете задания. Требует модуль «Задания»; без него — «!»."
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "Маркер и стрелка бледнеют в бою, чтобы никогда не мешать."
L["The marker in the world that leads you to your quest."] = "Маркер в мире, ведущий к вашему заданию."
L["The marker over the spot of the quest you picked (click its icon in the tracker) in DaylightUI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "Маркер над местом выбранного задания (щелкните его значок в трекере) в стиле DaylightUI, с расстоянием. Он исчезает, когда вы попадаете в область задания на карте. Отключите, чтобы видеть маркер игры."
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "Цвет полос ближнего боя, пока «Удар героя», «Рассекающий удар» или «Трепка» ждут следующего удара."
L["The meter hides while you play solo."] = "Счетчик скрывается, когда вы играете в одиночку."
L["The most buff icons at once."] = "Наибольшее число значков положительных эффектов одновременно."
L["The most buffs you can purge or steal one plate shows."] = "Наибольшее число эффектов, которые можно развеять или украсть, на одном индикаторе."
L["The most debuff icons at once."] = "Наибольшее число значков отрицательных эффектов одновременно."
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "Наибольшее число отрицательных эффектов от других игроков, после ваших. Только с «Сначала мои, затем чужие»."
L["The most group members the threat meter lists at once, under the damage meter."] = "Наибольшее число участников группы в счетчике угрозы одновременно, под счетчиком урона."
L["The most group members the threat meter lists at once."] = "Наибольшее число участников группы в счетчике угрозы одновременно."
L["The most icons this group shows at once."] = "Наибольшее число значков этой группы одновременно."
L["The most of your buffs one friendly plate shows."] = "Наибольшее число ваших положительных эффектов на одном индикаторе союзника."
L["The most of your debuffs one plate shows."] = "Наибольшее число ваших отрицательных эффектов на одном индикаторе."
L["The most of your own debuffs shown at once."] = "Наибольшее число ваших отрицательных эффектов одновременно."
L["The mouseover border's color when Mouseover border color is set to Your own color."] = "Цвет каймы при наведении, когда «Цвет каймы при наведении» — «Ваш цвет»."
L["The name floats above the bar, at its outer end. Long names are cut short."] = "Имя парит над полосой, у ее внешнего конца. Длинные имена обрезаются."
L["The name of a buff or debuff as it lands on you."] = "Название положительного или отрицательного эффекта, когда он на вас накладывается."
L["The name sits in a small tab above the frame. Long names are cut short."] = "Имя находится на маленькой вкладке над рамкой. Длинные имена обрезаются."
L["The name's color when Name color is Custom."] = "Цвет имени, когда «Цвет имени» — «Вручную»."
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "Имена на всех рамках портретов, если рамка не выбирает свой цвет. Класс и отношение: игроки — цветом класса, остальные — по отношению: дружелюбные, нейтральные или враждебные."
L["The names' color when Name color is Custom."] = "Цвет имен, когда «Цвет имени» — «Вручную»."
L["The newest first. Click one to move it again."] = "Сначала новые. Щелкните, чтобы переместить снова."
L["The note box shows after the fight."] = "Поле заметки появится после боя."
L["The number on an icon showing how many stacks it has."] = "Число на значке, показывающее количество стопок."
L["The numbers change color for the last seconds of the cooldown."] = "Цифры меняют цвет в последние секунды восстановления."
L["The numbers in objectives, like 3/8."] = "Числа в задачах, например 3/8."
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "Числа на полосе, например 1,200 / 5,000 (+800), где +800 — ваш опыт отдыха."
L["The numbers over what you hit."] = "Числа над теми, кого вы бьете."
L["The off hand bar's color."] = "Цвет полосы левой руки."
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "Форма, по которой вырезается каждая кнопка. Значок, кайма и тень восстановления следуют ей."
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "Контур или свечение в акцентном цвете (Внешность), меняется вместе с ним. Если выключено, используются цвета ниже."
L["The outline's color when Target outline color is Custom color."] = "Цвет контура, когда «Цвет контура цели» — «Свой цвет»."
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "Панель за чатом с каймой. Если выключено, показывается только текст чата."
L["The panel's framed box behind the list, as tall as what's shown."] = "Обрамленная подложка панели за списком, высотой с показанное."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "Полоса здоровья питомца принимает цвет настроения: красный — недоволен, желтый — доволен, зеленый — счастлив. Выключите квадрат, чтобы осталось только это."
L["The pets' health text. General uses the font on General > Appearance."] = "Текст здоровья питомцев. «Общий» использует шрифт из Общий > Внешность."
L["The pets' names. General uses the font on General > Appearance."] = "Имена питомцев. «Общий» использует шрифт из Общий > Внешность."
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "Только что заработанный кусок полосы вспыхивает, и всплывает «+XP»; при повышении уровня — развертка. Требует «Эффекты движения» (Общий > Внешность)."
L["The pips widen to span the whole frame, so the row reads like a bar."] = "Деления растягиваются на всю рамку, и ряд выглядит как полоса."
L["The pips' color with One color, or the color they start from with Color to full color."] = "Цвет делений при «Один цвет» или начальный цвет при «Цвет до полного»."
L["The players who keep DaylightUI going. Thank you."] = "Игроки, благодаря которым DaylightUI живет. Спасибо."
L["The power bar's color when Power bar color is One color."] = "Цвет полосы ресурса, когда «Цвет полосы ресурса» — «Один цвет»."
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "Текст ресурса показывается и при полной мане, ярости или энергии. Если выключено, он исчезает при полном запасе."
L["The pressed border's color when Pressed border color is set to Your own color."] = "Цвет каймы при нажатии, когда «Цвет каймы при нажатии» — «Ваш цвет»."
L["The priority quest's color while Priority quest color is set to Custom."] = "Цвет приоритетного задания, когда «Цвет приоритетного задания» — «Вручную»."
L["The proc border's color when Proc border is set to Your own color."] = "Цвет каймы срабатывания, когда «Кайма срабатывания» — «Ваш цвет»."
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "Профиль %s готов. Выберите его для этого персонажа (или набора талантов), чтобы использовать."
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "Профиль %s: его настройки, положения рамок и макет режима редактирования. Ctrl+C — скопировать, затем поделитесь им."
L["The profile for your first talent set. Changing it asks to reload."] = "Профиль для первого набора талантов. При смене будет предложено перезагрузить интерфейс."
L["The profile for your second talent set; swapping talents asks to switch."] = "Профиль для второго набора талантов; при смене талантов будет предложено переключиться."
L["The profile in use as text to copy and share."] = "Текущий профиль в виде текста, чтобы скопировать и поделиться."
L["The profile is ready. Reload to use it."] = "Профиль готов. Перезагрузите интерфейс, чтобы использовать его."
L["The profile is used as it is; nothing in it changes."] = "Профиль используется как есть; в нем ничего не меняется."
L["The profile this character uses. Changing it asks to reload."] = "Профиль этого персонажа. При смене будет предложено перезагрузить интерфейс."
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "Макет режима редактирования этого профиля будет установлен после перезагрузки (%s)."
L["The progress bars' color while Progress bar color is set to Custom."] = "Цвет полос прогресса, когда «Цвет полосы прогресса» — «Вручную»."
L["The quest log on the world map."] = "Журнал заданий на карте мира."
L["The quest under the mouse stays bright, the others ease dimmer."] = "Задание под курсором остается ярким, остальные плавно тускнеют."
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Рамки рейда для 11–20 игроков. Показ, угасание, текстуры и шрифты — на странице «Рейд 10»."
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Рамки рейда для 21–40 игроков. Показ, угасание, текстуры и шрифты — на странице «Рейд 10»."
L["The raid tiles' health text. General uses the font on General > Appearance."] = "Текст здоровья плиток рейда. «Общий» использует шрифт из Общий > Внешность."
L["The raid tiles' names. General uses the font on General > Appearance."] = "Имена на плитках рейда. «Общий» использует шрифт из Общий > Внешность."
L["The raid tiles' own name color. Same as the Colors page follows the name color every frame shares."] = "Собственный цвет имен плиток рейда. «Как на странице \"Цвета\"» следует общему для всех рамок цвету имен."
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "Полоса дальнего боя показывает расстояние до цели вместо ее имени: ближний бой, мертвая зона, 10–35 м, предельная дальность или вне зоны действия."
L["The ranged bar's color."] = "Цвет полосы дальнего боя."
L["The red of a ring, name tab or raid tile while something is attacking the unit, or a color you pick."] = "Красный цвет кольца, вкладки имени или плитки рейда, пока существо атакуют, или выбранный вами цвет."
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "Кольцо (или вкладка имени, или плитка рейда) краснеет, пока существо атакуют; дракон элиты сохраняет свой цвет, а его глаза загораются."
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "Значок роли остается в бою. Если выключено, он скрывается, пока вы сражаетесь."
L["The row above the bar that holds the name and the health number."] = "Ряд над полосой с именем и числом здоровья."
L["The same click again removes it."] = "Повторный такой же щелчок удаляет его."
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "Те же цвета, что в настройках чата игры: изменение видно во всех вкладках чата."
L["The same size as the top-right panel with its damage meter out."] = "Тот же размер, что у правой верхней панели с вынесенным счетчиком урона."
L["The search failed. Try Refresh."] = "Поиск не удался. Нажмите «Обновить»."
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "Затенение здоровья, которое еще снимут ваши периодические заклинания, на цели и на индикаторах противников."
L["The shade that sweeps over a button while it's on cooldown."] = "Тень, проходящая по кнопке во время восстановления."
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "Размер символов входов, распорядителей полетов, кораблей и дирижаблей на карте мира. Они сохраняют размер при масштабировании."
L["The skull, star and other raid markers just left of the bar."] = "Череп, звезда и другие рейдовые метки слева от полосы."
L["The slim health bar. The name, the health number and the power line sit outside it."] = "Тонкая полоса здоровья. Имя, число здоровья и линия ресурса находятся снаружи."
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "Маленькая вкладка у левого края счетчика (появляется, когда курсор рядом) выдвигает его или убирает вручную."
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "Маленькая вкладка с именем над рамкой: ее кайма, углы, тень, место и ширина."
L["The small zone names over each group of quests."] = "Мелкие названия зон над каждой группой заданий."
L["The soft light behind the model on the Character page."] = "Мягкий свет за моделью на странице «Персонаж»."
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "Мягкий свет за моделью на странице «Персонаж». Если выключено, виден только фон окна."
L["The sound when someone whispers you. The first five are gentle chimes made for DaylightUI; picking one plays it once."] = "Звук при входящем шепоте. Первые пять — мягкие перезвоны, сделанные для DaylightUI; при выборе звук проигрывается один раз."
L["The space between the health bar and the power line under it."] = "Расстояние между полосой здоровья и линией ресурса под ней."
L["The spell an enemy is casting, under its health bar."] = "Заклинание, которое применяет противник, под его полосой здоровья."
L["The spell being cast, as a small icon left of the cast bar."] = "Применяемое заклинание маленьким значком слева от индикатора заклинаний."
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "Название заклинания и время на индикаторах заклинаний. «Общий» использует шрифт из Общий > Внешность."
L["The spell name and time on your cast bar."] = "Название заклинания и время на вашем индикаторе заклинаний."
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "Название заклинания и время на вашем индикаторе заклинаний. «Общий» использует шрифт из Общий > Внешность."
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "Название заклинания и время на индикаторе заклинаний фокуса. «Общий» использует шрифт из Общий > Внешность."
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "Название заклинания и время на индикаторе заклинаний фокуса. Внутри рамки текст уменьшается, чтобы поместиться в полосу ресурса."
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "Название заклинания и время на индикаторе заклинаний цели. «Общий» использует шрифт из Общий > Внешность."
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "Название заклинания и время на индикаторе заклинаний цели. Внутри рамки текст уменьшается, чтобы поместиться в полосу ресурса, если не задан «Размер текста внутри рамки»."
L["The spell name and timer on the target's cast bar."] = "Название заклинания и таймер на индикаторе заклинаний цели."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "Название заклинания и таймер, пока полоса внутри рамки цели, даже выше полосы ресурса. 0 — использовать «Размер текста индикатора заклинаний цели», уменьшенный под полосу ресурса."
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "Значок заклинания в конце индикатора заклинаний фокуса. Не когда он внутри рамки."
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "Значок заклинания в конце индикатора заклинаний цели. Не когда он внутри рамки."
L["The spell's name on every cast bar."] = "Название заклинания на каждом индикаторе заклинаний."
L["The spell's own"] = "Цвет заклинания"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "Собственный цвет заклинания («Обновление» — зеленый, щит — синий) или выбранный вами."
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "Клавиши книги заклинаний и талантов открывают окно DaylightUI. В бою открывается книга игры, чтобы можно было перетаскивать заклинания на панели. Отключите, чтобы всегда использовать окно игры."
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "Книга заклинаний и таланты, окна профессий, книга профессий, стойла."
L["The square minimap in the panel."] = "Квадратная мини-карта в панели."
L["The square's color when Heal indicator color is Custom color."] = "Цвет квадрата, когда «Цвет индикатора исцеления» — «Свой цвет»."
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "Заголовки групп характеристик и заголовки на других страницах. У каждой свой: цвет для каждой группы характеристик, по очереди на других страницах."
L["The sweep can't start in combat."] = "Развертку нельзя запустить в бою."
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "Стрелка и время таймера удара. «Общий» использует шрифт из Общий > Внешность."
L["The tag after a PvP quest's title."] = "Метка после названия PvP-задания."
L["The tag after a dungeon quest's title."] = "Метка после названия задания подземелья."
L["The tag after a raid quest's title."] = "Метка после названия рейдового задания."
L["The tag after an elite quest's title."] = "Метка после названия элитного задания."
L["The talents you're using now."] = "Таланты, которые вы используете сейчас."
L["The target and focus cast bars' color for a moment after their cast is interrupted."] = "Цвет индикаторов заклинаний цели и фокуса сразу после прерывания."
L["The target and focus cast bars' color while they cast."] = "Цвет индикаторов заклинаний цели и фокуса во время применения."
L["The target and focus cast bars' color while they channel."] = "Цвет индикаторов заклинаний цели и фокуса во время поддержания."
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "Градиенты класса и ресурса у цели и цели выбранной цели идут в обратную сторону, зеркально вашим. Только для горизонтального градиента."
L["The text in DaylightUI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "Текст в окнах DaylightUI (персонаж, книга заклинаний, профессии, сумки, журнал заданий) и в окнах игры, которые он оформляет. «Общий» использует шрифт выше."
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "Текстуры выше показываются на всех полосах сразу, кроме мест, где страница рамки или полосы окон ниже выбирают другие. Эта кнопка возвращает их все к текстурам выше."
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "Тонкая линия под каждым заголовком. Как подчеркивание вкладки: то, что выбрано в «Подчеркивание вкладки» ниже. «Градиент класса» использует цвета вашего класса со страницы «Градиенты»."
L["The thin power bar under the health bar."] = "Тонкая полоса ресурса под полосой здоровья."
L["The thin strip under the minimap with gold, gear, bag space and more."] = "Тонкая полоска под мини-картой с золотом, экипировкой, местом в сумках и другим."
L["The threat bars' color when Bar color is One color."] = "Цвет полос угрозы, когда «Цвет полосы» — «Один цвет»."
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "Цвета угрозы медленно светлеют и тускнеют, быстрее, когда противник вот-вот сменит цель. Требует полосу здоровья, кайму или свечение выше."
L["The tick next to a finished objective."] = "Галочка рядом с выполненной задачей."
L["The time at the bottom of the minimap."] = "Время внизу мини-карты."
L["The time before each message (the game's own setting)."] = "Время перед каждым сообщением (настройка игры)."
L["The time left as a number on each icon."] = "Оставшееся время числом на каждом значке."
L["The time left on a timed quest once it's under a minute."] = "Оставшееся время задания с ограничением, когда осталось меньше минуты."
L["The time left on a timed quest."] = "Оставшееся время задания с ограничением."
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "Время на каждом индикаторе заклинаний: сколько осталось, сколько осталось из общего времени или ничего."
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "Оттенок кнопки, пока цель вне зоны действия, когда «Вне зоны действия» — «Окрасить значок»."
L["The tooltip text; titles are a little larger."] = "Текст подсказки; заголовки немного крупнее."
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode."] = "Правая верхняя панель: индикатор опыта сверху, счетчик урона и мини-карта под ним. Перемещайте ее в режиме открепления."
L["The two ends of the bar's gradient. With Gradient off, the bar takes the bright end."] = "Два конца градиента полосы. При выключенном градиенте полоса берет светлый конец."
L["The two-color fills bars use when set to a gradient (Class gradient on unit frames and nameplates, power bars)."] = "Двухцветные заливки для полос с градиентом («Градиент класса» на рамках портретов и индикаторах здоровья, полосы ресурса)."
L["The unit you set as focus."] = "Существо, назначенное фокусом."
L["The unit's health as text at the right end of the bar. Pick the format under Health text."] = "Здоровье существа текстом у правого конца полосы. Формат выбирается в «Текст здоровья»."
L["The unit's health written on this frame."] = "Здоровье существа текстом на этой рамке."
L["The unit's level at the left end of the bar, in the game's difficulty color; ?? for one far above you, + for an elite."] = "Уровень существа у левого конца полосы, в цвете сложности игры; ?? — намного выше вас, + — элита."
L["The whole Bank and alts window, slots, text and buttons together."] = "Все окно «Банк и альты»: ячейки, текст и кнопки вместе."
L["The whole bag window, slots, text and buttons together."] = "Все окно сумок: ячейки, текст и кнопки вместе."
L["The whole bank window, slots, text and buttons together."] = "Все окно банка: ячейки, текст и кнопки вместе."
L["The whole bar, icons, text and background together."] = "Вся полоса: значки, текст и фон вместе."
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "Вся лента. Также колесико мыши над ее ручкой в /dui unlock."
L["The whole group shows only during a fight."] = "Вся группа показывается только в бою."
L["The whole group shows only in a party or raid."] = "Вся группа показывается только в группе или рейде."
L["The whole pop-up, text and bar together."] = "Все всплывающее окно: текст и полоса вместе."
L["The window's title shows the player's last name after their first name."] = "В заголовке окна фамилия игрока показывается после имени."
L["The world map's quest list and quest pages in DaylightUI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "Список заданий и страницы заданий на карте мира в стиле DaylightUI, с кнопками «Следить», «Поделиться» и «Отменить» у каждого задания. Отключите, чтобы использовать вариант игры."
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "Зона или местность, где вы находитесь, вверху карты (над координатами)."
L["The zone or area you're in, at the top of the minimap."] = "Зона или местность, где вы находитесь, вверху мини-карты."
L["Their health as text at the right end of the bar."] = "Их здоровье текстом у правого конца полосы."
L["Their keybinds work even when hidden. Move them in unlock mode."] = "Их назначенные клавиши работают даже в скрытом виде. Перемещайте их в режиме открепления."
L["Their level at the left end of the bar."] = "Их уровень у левого конца полосы."
L["These are for talent set %s; each talent set keeps its own."] = "Это для набора талантов %s; у каждого набора талантов свои."
L["These talents use the profile %s. Switch to it?"] = "Эти таланты используют профиль %s. Переключиться на него?"
L["Thick"] = "Толстый"
L["Thin"] = "Тонкий"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "Тонкие линии делят полосу на 20 частей, как в классической полосе: каждая — 5% уровня."
L["This Legacy tree isn't available yet."] = "Это дерево наследия пока недоступно."
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "Размер имени этой полосы. «Размер текста» в разделе «Вся группа» задает размер для всех полос."
L["This character"] = "Этот персонаж"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "Этот персонаж не завершил мастер настройки, поэтому перемещенные рамки вернутся на место при выходе. Введите /dui install, чтобы завершить его."
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "Этот персонаж не завершил мастер настройки, поэтому все изменения и перемещения пропадут при выходе. Сначала завершите мастер, затем вносите изменения."
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "Для этого персонажа, для текущего набора талантов. Охватывает рамки игрока, цели, цели выбранной цели, питомца, фокуса, группы и рейда."
L["This client has no aura container; target auras are off."] = "В этом клиенте нет контейнера эффектов; эффекты цели отключены."
L["This fight"] = "Этот бой"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "Текст здоровья этой рамки и крупное число. «Общий» использует шрифт из Общий > Внешность."
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "Имена этой рамки и значок уровня. «Общий» использует шрифт из Общий > Внешность."
L["This frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares."] = "Собственный цвет здоровья этой рамки, чтобы она отличалась от других. «Как на странице \"Цвета\"» следует общему для всех рамок цвету."
L["This frame's own name color. Same as the Colors page follows the name color every frame shares."] = "Собственный цвет имени этой рамки. «Как на странице \"Цвета\"» следует общему для всех рамок цвету имен."
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "Собственный контур, углы и тень этой рамки, чтобы она выделялась на фоне остального интерфейса."
L["This frame's own power color. Same as the Colors page follows the color every frame shares."] = "Собственный цвет ресурса этой рамки. «Как на странице \"Цвета\"» следует общему для всех рамок цвету."
L["This frame's power text. General uses the font on General > Appearance."] = "Текст ресурса этой рамки. «Общий» использует шрифт из Общий > Внешность."
L["This group's header. The other pages use the six colors in turn."] = "Заголовок этой группы. Другие страницы используют шесть цветов по очереди."
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "Размер этого значка. «Вся группа» ниже задает размер всех значков группы."
L["This level"] = "Этот уровень"
L["This session"] = "Этот сеанс"
L["This set hasn't been used yet. Activate it to spend its points."] = "Этот набор еще не использовался. Активируйте его, чтобы распределить очки."
L["This setting"] = "Эта настройка"
L["This zone"] = "Эта зона"
L["This zone only"] = "Только эта зона"
L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Sound)."] = "Эти тихие ошибки вместо голосовой фразы издают один мягкий низкий щелчок, никогда не очередью. Следует настройке «Мягкие звуки интерфейса» (Общий > Звук)."
