L["Two-color gradient"] = "Двухцветный градиент"
L["Type"] = "Тип"
L["Type DELETE for me"] = "Вводить УДАЛИТЬ за меня"
L["Type a buff's name and pick where it belongs."] = "Введите название положительного эффекта и выберите, куда его поместить."
L["Uncommon (green) and up"] = "Необычные (зеленые) и выше"
L["Under a day"] = "Меньше суток"
L["Under its owner"] = "Под владельцем"
L["Under the action bars"] = "Под панелями команд"
L["Under the bar (the cast bar moves down) or over it (the name moves up)."] = "Под полосой (индикатор заклинаний сдвигается вниз) или над ней (имя сдвигается вверх)."
L["Under the cast bar"] = "Под индикатором заклинаний"
L["Under the frame (slides out)"] = "Под рамкой (выдвигается)"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "Под рамкой он продолжает скос рамки и выдвигается при применении заклинания. Над рамкой или отдельно у него свой размер."
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "Под рамкой он продолжает скос рамки. Если выключено, его конец прямой."
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "Под рамкой или над ней, не задевая имя. Положительные или отрицательные эффекты цели с этой стороны сдвигаются."
L["Under the meter"] = "Под счетчиком"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Под счетчиком он выдвигается из нижнего края счетчика урона внутри панели, шириной со счетчик, а строки счетчика освобождают место. Пристыкованный (слева или снизу), он показывается только при открытом счетчике урона. Отдельное окно можно разместить где угодно: перемещайте его в режиме открепления (/dui unlock) и тяните за угол, чтобы изменить размер."
L["Under the meter it's part of the panel, with no window of its own."] = "Под счетчиком он часть панели, без собственного окна."
L["Under the panel"] = "Под панелью"
L["Underline color"] = "Цвет подчеркивания"
L["Undo"] = "Отменить"
L["Unexplored area brightness"] = "Яркость неисследованных областей"
L["Unfold"] = "Развернуть"
L["Unfriendly"] = "Неприязнь"
L["Unhook it"] = "Отсоединить"
L["Unit Frames"] = "Рамки портретов"
L["Unknown"] = "Неизвестно"
L["Unknown command '%s'."] = "Неизвестная команда '%s'."
L["Unknown spell"] = "Неизвестное заклинание"
L["Unlearn"] = "Забыть навык"
L["Unlist"] = "Снять с публикации"
L["Unlock"] = "Открепить"
L["Unlock frames"] = "Открепить рамки"
L["Unlocked. Drag to move, scroll to resize, right-click to put back, /dui lock when done."] = "Откреплено. Перетаскивайте для перемещения, прокручивайте для изменения размера, правый щелчок — вернуть на место, /dui lock — когда закончите."
L["Unpin"] = "Открепить"
L["Untrack"] = "Не отслеживать"
L["Untrack all"] = "Не отслеживать все"
L["Up"] = "Вверх"
L["Up and Down scroll the text in a straight line. Arc bursts it out to the side and curves it up."] = "«Вверх» и «Вниз» прокручивают текст по прямой. «Дуга» выбрасывает его в сторону и изгибает вверх."
L["Up early. Even the murlocs are still asleep."] = "Рано встали. Даже мурлоки еще спят."
L["Up to three, at the debuffs' size, with a countdown. They only appear when a boss uses them. With the game's buff frames shown, the game shows them there instead."] = "До трех, размером с отрицательные эффекты, с отсчетом. Появляются, только когда их использует босс. Если показаны окна эффектов игры, игра показывает их там."
L["Up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "До двух больших значков в центре, с разверткой оставшегося времени. Появляются, только когда их использует босс."
L["Up: newest at the bottom"] = "Вверх: новые снизу"
L["Update"] = "Обновить"
L["Usable glow color"] = "Цвет свечения доступности"
L["Usable"] = "Доступно"
L["Usage: /dui buffs toggle <category name>"] = "Использование: /dui buffs toggle <название категории>"
L["Use"] = "Использовать"
L["Use DaylightUI's"] = "Вариант DaylightUI"
L["Use DaylightUI's Cooldown Manager"] = "Использовать трекер восстановления DaylightUI"
L["Use DaylightUI's quest tracker"] = "Использовать трекер заданий DaylightUI"
L["Use a setup I have"] = "Использовать мою настройку"
L["Use accent color"] = "Использовать акцентный цвет"
L["Use guild money first"] = "Сначала деньги гильдии"
L["Use my language's font"] = "Шрифт для моего языка"
L["Use my layout on this character"] = "Использовать мой макет на этом персонаже"
L["Use raid frames in a party"] = "Рамки рейда в группе"
L["Use this"] = "Использовать это"
L["Use this font for the game's text"] = "Использовать этот шрифт для текста игры"
L["Use this heal indicator"] = "Использовать этот индикатор исцеления"
L["Used by all DaylightUI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed after ours."] = "Используется всем текстом DaylightUI, кроме мест, где страница рамки выбирает другой шрифт. «Шрифт игры» — собственный шрифт клиента, включая шрифт, которым вы его заменили. Шрифты других модификаций (SharedMedia) идут после наших."
L["Used when Unit Frames > Extras > Combo points > Colors is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "Используется, когда Рамки портретов > Дополнительно > Приемы серии > Цвета — градиент: «Все очки» заполняет все деления одной парой, «Очко 1–5» дает каждому делению свою."
L["Uses the Raid 10 frames, and the rows below are grayed out. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "Использует рамки «Рейд 10», а строки ниже недоступны. Отключите, чтобы дать этому размеру рейда свои настройки, начиная с копии «Рейд 10»."
L["Uses the game's own font in place of DaylightUI's fonts, which only have Latin letters. The options window changes after /reload."] = "Использует шрифт игры вместо шрифтов DaylightUI, в которых есть только латиница. Окно параметров изменится после /reload."
L["Usually General."] = "Обычно «Общий»."
L["Usually Local Defense."] = "Обычно «Оборона»."
L["Usually Looking for Group."] = "Обычно «ПоискСпутников»."
L["Usually Trade."] = "Обычно «Торговля»."
L["Usually a skill point"] = "Обычно очко навыка"
L["Varela Round"] = "Varela Round"
L["Vendor window"] = "Окно торговца"
L["Vendors"] = "Торговцы"
L["Vendors open in the NPC window too, with their goods on a shelf. Turn it off to use the game's vendor window."] = "Торговцы тоже открываются в окне НИП, с товарами на полке. Отключите, чтобы использовать окно торговца игры."
L["Version %s."] = "Версия %s."
L["Vertical (light on top)"] = "Вертикально (светлый сверху)"
L["Vertical bar"] = "Вертикальная полоса"
L["View distance (yards)"] = "Дальность обзора (м)"
L["Visibility"] = "Отображение"
L["Visible"] = "Видимость"
L["Waist"] = "Пояс"
L["Wait for the talents being applied."] = "Дождитесь применения талантов."
L["Walking Boots"] = "Прогулочные сапоги"
L["Warmed by the fire"] = "Согрелись у костра"
L["Warlock"] = "Чернокнижник"
L["Warm bell"] = "Теплый колокол"
L["Warns you when a mob is about to change target, or has."] = "Предупреждает, когда противник вот-вот сменит цель или уже сменил."
L["Warrior"] = "Воин"
L["Weapon"] = "Оружие"
L["Weapon Enchant"] = "Чары на оружии"
L["Weapon icon"] = "Значок оружия"
L["Weapon master"] = "Мастер оружия"
L["Weapons"] = "Оружие"
L["Wearing it"] = "Надето"
L["Web addresses in messages become links; click one to copy it."] = "Веб-адреса в сообщениях становятся ссылками; щелкните, чтобы скопировать."
L["Website: %s"] = "Сайт: %s"
L["Welcome"] = "Добро пожаловать"
L["Went out"] = "Ушел"
L["What Alt-click on a quest in the tracker does."] = "Действие Alt-щелчка по заданию в трекере."
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "Что делает кнопка, пока цель вне зоны действия. Нехватка маны, ярости или энергии действует так же (синим при окрашивании)."
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "Действие щелчка по заданию в трекере. Щелчок по его значку всегда делает задание приоритетным, а правый щелчок открывает его меню."
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "Род занятий дружественного НИП (Хозяин таверны, Распорядитель полетов...) под его именем, мельче."
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "Род занятий НИП (Снятие шкур, Распорядитель полетов...) под его именем, мельче. Не в подземельях."
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "Что происходит с прерванным индикатором заклинаний: «Клинок» разрезает его надвое, «Осколки» разбивают на осколки, «Излом» ломает посередине, «Выгорание» выжигает заливку, «Перемотка» отбрасывает ее до пустоты, «Ударная волна» выпускает из него вспышку света, «Угасание» дает свету вытечь. Ваши собственные прерывания подсвечиваются акцентным цветом. Наведите курсор на вариант, чтобы увидеть его в предпросмотре."
L["What changed in each version."] = "Что изменилось в каждой версии."
L["What changed in each version. Click a version to open or close it."] = "Что изменилось в каждой версии. Щелкните по версии, чтобы развернуть или свернуть ее."
L["What each enemy plate shows on and around its bar, and its colors."] = "Что показывает каждый индикатор противника на полосе и вокруг нее, и его цвета."
L["What each item's icon shows in the Bank and alts window."] = "Что показывает значок каждого предмета в окне «Банк и альты»."
L["What each item's icon shows in the bank."] = "Что показывает значок каждого предмета в банке."
L["What each item's icon shows."] = "Что показывает значок каждого предмета."
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "Что показывает каждая ячейка, слева направо. Часы, частота кадров и координаты есть и на мини-карте."
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "Что происходит с уже записанными боями, когда вы входите в подземелье, рейд или на поле боя: сохранить их, спросить о сбросе или сразу сбросить. Возвращение после смерти не считается."
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "Что происходит с уже записанными боями, когда вы вступаете в группу: сохранить, спросить о сбросе или сразу сбросить."
L["What it shows"] = "Что показывает"
L["What sits between the text's parts."] = "Что стоит между частями текста."
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "Что показывает счетчик: урон, исцеление, полученный урон, прерывания, рассеивания, смерти и другое. Кнопка на счетчике тоже это меняет."
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "Что показывает второй счетчик: урон, исцеление, полученный урон, прерывания, рассеивания, смерти и другое."
L["What the target's or focus's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "Что делает индикатор заклинаний цели или фокуса, когда заклинание прервано. Ваши собственные прерывания подсвечиваются акцентным цветом."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "Что делает трекер, когда вы входите в подземелье, рейд или на поле боя. Он возвращается, когда вы выходите."
L["What this extra text shows first, like the name, the level or the guild."] = "Что этот дополнительный текст показывает первым, например имя, уровень или гильдию."
L["What this group takes. Click to change."] = "Что берет эта группа. Щелкните, чтобы изменить."
L["What this slot on the data text strip shows. Slots count from the left."] = "Что показывает эта ячейка полоски информационных текстов. Ячейки считаются слева."
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "Ваша добыча и повышения навыков, выезжающие лентами справа внизу."
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "Ваша добыча выезжает справа внизу экрана в цвете качества, одинаковые предметы прибавляются к счетчику, а через несколько секунд строка угасает. Наведите на строку, чтобы увидеть подсказку предмета. Перемещайте ленту через /dui unlock."
L["What's Training is still reading your spells."] = "«Что изучить» еще читает ваши заклинания."
L["What's included"] = "Что входит"
L["When Threat colors are on, they replace this color while showing."] = "Когда цвета угрозы включены, они заменяют этот цвет, пока показываются."
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "Когда положительный эффект заканчивается, следующие заклинания сдвигаются на его место. Если выключено, каждое заклинание остается на своем месте. Заклинание с «Сохранять место» (вкладка «Поведение») сохраняет его в любом случае."
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "Когда заклинание прервано, полоса на мгновение остается полной с надписью «Прервано»."
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "Когда НИП может предложить только одно (торговец, распорядитель полетов, банкир или учитель) и у него нет заданий, его окно открывается сразу. Удерживайте Shift, чтобы увидеть диалог."
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "Когда автодобыча включена, все подбирается сразу, а не по одному предмету."
L["When hovering a button shows its spell or item tooltip."] = "Когда наведение на кнопку показывает подсказку заклинания или предмета."
L["When it shows"] = "Когда показывать"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "Если выключено, показывается любой отрицательный эффект с типом (магия, проклятие, болезнь, яд), даже тот, который вы не можете снять."
L["When off, the game's own bag windows are used."] = "Если выключено, используются окна сумок игры."
L["When off, the game's tracker stays where Edit Mode puts it."] = "Если выключено, трекер игры остается там, где его ставит режим редактирования."
L["When ready"] = "Когда готово"
L["When the accent color is a gradient (Daylight's or your class's), window borders run along it."] = "Когда акцентный цвет — градиент (Daylight или вашего класса), каймы окон идут вдоль него."
L["When the shown bag bar fades and how far."] = "Когда показанная панель сумок угасает и насколько."
L["When the shown micro menu fades and how far."] = "Когда показанное микроменю угасает и насколько."
L["When to show"] = "Когда показывать"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "Когда вы уничтожаете хороший предмет, поле подтверждения заполняется. Кнопку вы все равно нажимаете сами."
L["When you dodge, parry or an attack misses you."] = "Когда вы уклоняетесь, парируете или по вам промахиваются."
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "Когда вы отходите, мир темнеет, интерфейс угасает, а ваш персонаж стоит рядом с карточкой с вашим именем, зоной, опытом отдыха и забавным фактом. Двиньтесь, щелкните или нажмите любую клавишу, чтобы вернуться. Никогда в бою, в битвах с боссами, эпохальных ключах или PvP-матчах."
L["When you have forms"] = "Когда есть формы"
L["When you have totems"] = "Когда есть тотемы"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "Когда попадет ваша следующая автоатака: по полосе на каждую руку, которой вы бьете."
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "Где показываются «Прервал» и имя: рядом с индикатором заклинаний или под ним."
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "С какого места рамки начинается ряд: со скошенного конца, обращенного к центру экрана, с середины или с дальнего конца."
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "В каком месте верха рамки находится вкладка. Вкладка во всю ширину всегда начинается с внешнего конца. Или перетащите вкладку в режиме дизайна."
L["Where along the power bar the power text sits."] = "Где на полосе ресурса находится текст ресурса."
L["Where new lines come in."] = "Откуда появляются новые строки."
L["Where on the button its key shows."] = "Где на кнопке показывается клавиша."
L["Where on the frame this square sits."] = "Где на рамке находится этот квадрат."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "Где появляется поле ввода. «Под панелью» оставляет для него полоску под чатом, чтобы оно никогда не закрывало текст."
L["Where the dispel icon sits on each frame, or just outside it."] = "Где находится значок рассеивания на каждой рамке или прямо за ней."
L["Where the interrupter's name shows: right of the cast bar or under it."] = "Где показывается имя прервавшего: справа от индикатора заклинаний или под ним."
L["Where the leader crown sits on each frame, or just outside it."] = "Где находится корона лидера на каждой рамке или прямо за ней."
L["Where the name sits across the bar, while it's on the bar: left, center or right."] = "Где находится имя поперек полосы, пока оно на полосе: слева, по центру или справа."
L["Where the name sits across the bar: left, center or right."] = "Где находится имя поперек полосы: слева, по центру или справа."
L["Where the name sits inside its tab: left, center or right."] = "Где находится имя внутри вкладки: слева, по центру или справа."
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "Где открываются числа при наведении на полосу. «Автоматически» открывает их к центру экрана."
L["Where the raid marker sits on each frame, or just outside it."] = "Где находится рейдовая метка на каждой рамке или прямо за ней."
L["Where the ready check answer sits on each frame, or just outside it."] = "Где находится ответ на проверку готовности на каждой рамке или прямо за ней."
L["Where the role icon sits on each frame, or just outside it."] = "Где находится значок роли на каждой рамке или прямо за ней."
L["Where the role, marker, crown and dispel icons sit on a tile."] = "Где на плитке находятся значки роли, метки, короны и рассеивания."
L["Where things sit on your screen."] = "Где все находится на экране."
L["Where this category sits on the bar."] = "Где эта категория находится на полосе."
L["Where this extra text sits on the frame, or just outside it."] = "Где этот дополнительный текст находится на рамке или прямо за ней."
L["Where this group sits in the bag."] = "Где эта группа находится в сумке."
L["Where you put it"] = "Куда вы его положили"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "Где находятся ваши рамки. Лекари получают группу большими плитками в центре экрана."
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "Каждая рейдовая группа — столбец (рядом друг с другом) или строка (одна под другой)."
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "Считает ли счетчик текущий бой или все бои с последнего сброса."
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "Скошен ли конец вкладки имени. «Как у рамки» следует собственному концу рамки."
L["Whether the party frames stack down or line up across."] = "Располагаются ли рамки группы вниз или в ряд."
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "Считает ли второй счетчик текущий бой или все бои с последнего сброса."
L["Whether this extra group shows debuffs or buffs."] = "Показывает ли эта дополнительная группа отрицательные или положительные эффекты."
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "Уходят ли ваши панели и рамка в сторону, когда вы не сражаетесь. Позже у каждой части будет своя настройка «Видимость»."
L["Which bar the rows below set."] = "Какую полосу задают строки ниже."
L["Which buffs show."] = "Какие положительные эффекты показываются."
L["Which buffs this group shows."] = "Какие положительные эффекты показывает эта группа."
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "Какие кнопки меняют строки внешнего вида на этой странице. Панель хранит то, что вы для нее изменили; остальное следует «Все панели»."
L["Which corner of the button its count shows in."] = "В каком углу кнопки показывается ее счетчик."
L["Which debuffs show."] = "Какие отрицательные эффекты показываются."
L["Which debuffs this group shows."] = "Какие отрицательные эффекты показывает эта группа."
L["Which end of the group stays put when a spell in it hides."] = "Какой конец группы остается на месте, когда заклинание в ней скрывается."
L["Which frame the pips sit on."] = "На какой рамке находятся деления."
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "Какая клавиша принимает, продолжает и завершает. Enter также открывает чат."
L["Which numbers"] = "Какие числа"
L["Which of the six squares the rows below set."] = "Какой из шести квадратов задают строки ниже."
L["Which part's fade the rows below set."] = "Угасание какой части задают строки ниже."
L["Which quest tracker?"] = "Какой трекер заданий?"
L["Which side of its owner's frame each pet bar sits on."] = "С какой стороны рамки владельца находится каждая полоса питомца."
L["Which side of the list the quest item buttons sit on."] = "С какой стороны списка находятся кнопки предметов заданий."
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "Какие группы характеристик открыты сначала. По классу и специализации: «Характеристики» и та, что важна для вас. Группы, которые вы раскрываете или сворачиваете сами, запоминаются для каждого персонажа."
L["Which way the color runs along a bar."] = "В какую сторону цвет идет вдоль полосы."
L["Which way the row adds its icons, starting from its position."] = "В какую сторону ряд добавляет значки от своей позиции."
L["Which way the row of icons fills from its first icon."] = "В какую сторону ряд значков заполняется от первого значка."
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "Пока «Удар героя», «Рассекающий удар» или «Трепка» ждут следующего удара, полосы ближнего боя меняют цвет и показывают название."
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "При перемещении рамок края и центры выравниваются по другим рамкам. Удерживайте Shift, чтобы поставить куда угодно."
L["While possessing"] = "При контроле разума"
L["While swinging"] = "Во время атаки"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "Во время атаки: каждая полоса только пока идет ее замах, между ударами ее нет. В бою: все полосы, пока вы сражаетесь."
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "Пока положительного или отрицательного эффекта нет, он сохраняет место в виде серого значка или пустой полосы, чтобы было видно, чего не хватает."
L["While the panel is away, how long each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "Пока панель скрыта, сколько держится каждое сообщение до угасания. Новое сообщение не возвращает старые. Наведите курсор на чат, чтобы снова увидеть все."
L["While you cast, the power the spell will use is shaded on your power bar."] = "Пока вы применяете заклинание, ресурс, который оно потратит, затеняется на полосе ресурса."
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "Когда у вас лук, ружье, арбалет, метательное оружие или жезл."
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "Пока у вас есть цель, все остальные индикаторы угасают, чтобы цель выделялась. Индикатор, начавший применять заклинание, возвращается к полной видимости."
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Width, Health bar height and Scale)."] = "Пока у вас есть цель, индикатор цели и все остальные индикаторы используют размеры ниже (относительно «Ширина», «Высота шкалы здоровья» и «Масштаб»)."
L["While you have a weapon in your off hand."] = "Когда в левой руке есть оружие."
L["Whisper"] = "Шепот"
L["Whisper %s"] = "Шепнуть: %s"
L["Whisper color"] = "Цвет шепота"
L["Whisper sound"] = "Звук шепота"
L["Whispered"] = "Шепнул"
L["Battle.net whispers"] = "Шепот Battle.net"
L["Whispers"] = "Шепот"
L["Whispers from your Battle.net friends, and yours to them."] = "Шепот от друзей Battle.net и ваш шепот им."
L["Whispers in their own tab"] = "Шепот в отдельной вкладке"
L["Whispers you get and send."] = "Входящий и исходящий шепот."
L["White"] = "Белый"
L["White, the unit's class color, or one you pick."] = "Белый, цвет класса существа или выбранный вами."
L["Who"] = "Кто"
L["Who a player or creature is targeting, in their color (\">> You <<\" when it's you)."] = "На кого нацелен игрок или существо, в его цвете (\">> Вы <<\", если это вы)."
L["Who interrupted position"] = "Положение имени прервавшего"
L["Who to whisper?"] = "Кому шепнуть?"
L["Who your target is looking at."] = "На кого смотрит ваша цель."
L["Who's closest to pulling your target, in a small window that slides out of the damage meter's left edge, along its bottom, or anywhere on its own."] = "Кто ближе всех к срыву агро с вашей цели, в маленьком окне, выезжающем из левого края счетчика урона, вдоль его низа или где угодно отдельно."
L["Whole bar"] = "Вся полоса"
L["Whole group"] = "Вся группа"
L["Whole row in full color at max points"] = "Весь ряд полным цветом при максимуме очков"
L["Width"] = "Ширина"
L["William Pestle"] = "Уильям Пестл"
L["Window"] = "Окно"
L["Window background opacity"] = "Видимость фона окон"
L["Window bar background"] = "Фон полос окон"
L["Window bar texture"] = "Текстура полос окон"
L["Window border"] = "Кайма окон"
L["Window font"] = "Шрифт окон"
L["Window height"] = "Высота окна"
L["Window scale"] = "Масштаб окна"
L["Windows"] = "Окна"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "Окна плавно появляются и исчезают, подсказки проявляются, значок заклинания вспыхивает, когда оно готово, золото и опыт отсчитываются. Если выключено, все встает на место мгновенно."
L["Windows open & close"] = "Открытие и закрытие окон"
L["Wisdom"] = "Мудрость"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "С «Сохранять место» (нет эффекта) показывается, только когда его нужно применить, как «Боевой крик»."
L["With a pet"] = "С питомцем"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "Если включены оба, показывается только в группе и в бою. Второй счетчик тоже следует этим настройкам."
L["With chat open, Shift-click links the quest first."] = "При открытом чате Shift-щелчок сначала вставляет ссылку на задание."
L["With items in categories, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "С предметами по категориям стопки одного предмета показываются как одна, с общим количеством. Они показываются отдельно, пока вы торгуете или открыт почтовый ящик либо аукционный дом, чтобы можно было разделить одну Shift-щелчком."
L["With items in categories, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "С предметами по категориям осколки души показываются как один, с их количеством, хотя каждый по-прежнему занимает свою ячейку."
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "Без портрета и вкладки имени значки роли, метки, короны и рассеивания находятся в углах рамки."
L["Withdraw"] = "Съем"
L["Withdraw gold"] = "Снятие золота"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "Внутри каждой зоны. «Недавний прогресс» поднимает задание, когда засчитывается убийство, предмет или задача. «Сначала ближайшие» пересматривает порядок каждые несколько секунд, пока вы движетесь, но никогда в бою или подземелье. В бою ничего не сдвигается."
L["Wood pop"] = "Деревянный щелчок"
L["World"] = "Мир"
L["World map"] = "Карта мира"
L["World markers"] = "Метки на местности"
L["World of Warcraft"] = "World of Warcraft"
L["Wowhead link"] = "Ссылка Wowhead"
L["Wowhead link (Ctrl+C copies it):"] = "Ссылка Wowhead (Ctrl+C копирует ее):"
L["Wrists"] = "Запястья"
L["Write a letter..."] = "Написать письмо..."
L["Write a note to list for %s."] = "Напишите заметку к заявке для %s."
L["Write a subject."] = "Напишите тему."
L["Write the full name: first and last."] = "Напишите полное имя: имя и фамилию."
L["XP"] = "Опыт"
L["XP bar"] = "Индикатор опыта"
L["XP bar position"] = "Положение индикатора опыта"
L["XP bar, damage meter and a square minimap in one corner panel."] = "Индикатор опыта, счетчик урона и квадратная мини-карта в одной угловой панели."
L["XP gain effects"] = "Эффекты получения опыта"
L["Yards under the arrow"] = "Метры под стрелкой"
L["Yell color"] = "Цвет крика"
L["Yes"] = "Да"
L["You"] = "Вы"
L["You block about 1 in %d attacks with your shield."] = "Вы блокируете щитом примерно 1 атаку из %d."
L["You can also drag the chat's bottom-right corner to size it."] = "Чат также можно растянуть за правый нижний угол."
L["You can also switch with the button next to its search box."] = "Переключить можно и кнопкой рядом с его полем поиска."
L["You can also switch with the button next to the bank's search box."] = "Переключить можно и кнопкой рядом с полем поиска банка."
L["You can also switch with the button next to the search box."] = "Переключить можно и кнопкой рядом с полем поиска."
L["You can make %d"] = "Можно изготовить: %d"
L["You can reach rank %d this week"] = "На этой неделе можно достичь звания %d"
L["You can track up to %d quests."] = "Можно отслеживать до %d заданий."
L["You can't parry yet."] = "Вы пока не умеете парировать."
L["You carry %s."] = "У вас при себе: %s."
L["You choose one of these:"] = "Выберите одно из этого:"
L["You dodge about 1 in %d attacks."] = "Вы уклоняетесь примерно от 1 атаки из %d."
L["You don't block yet."] = "Вы пока не блокируете."
L["You don't dodge attacks yet."] = "Вы пока не уклоняетесь от атак."
L["You don't have that much gold."] = "У вас нет столько золота."
L["You get back %.0f mana every 5 seconds while not casting."] = "Вы восполняете %.0f ед. маны каждые 5 секунд, когда не применяете заклинания."
L["You keep"] = "Вы сохраняете"
L["You parry about 1 in %d attacks from the front."] = "Вы парируете примерно 1 атаку спереди из %d."
L["You shoot every %.2f seconds. Lower is faster."] = "Вы стреляете каждые %.2f с. Меньше — быстрее."
L["You'll also get:"] = "Вы также получите:"
L["You'll choose one of these:"] = "Вы сможете выбрать одно из этого:"
L["You're in a group: the leader tools work for real. Leave the group to practice with sample members."] = "Вы в группе: инструменты лидера работают по-настоящему. Покиньте группу, чтобы потренироваться на примерных участниках."
L["You're in combat; this finishes as soon as it ends."] = "Вы в бою; это завершится, как только бой закончится."
L["You're not in a guild."] = "Вы не состоите в гильдии."
L["You're not in a raid."] = "Вы не в рейде."
L["You've already learned talents this build doesn't have. A trainer can reset them."] = "Вы уже изучили таланты, которых нет в этой сборке. Сбросить их может учитель."
L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in DaylightUI style."] = "Ваши очки наследия, их награды, испытания, за которые их дают, и деревья наследия — в одном окне, в стиле DaylightUI."
L["Your accent, when the accent color is set to Custom color."] = "Ваш акцентный цвет, когда «Акцентный цвет» — «Свой цвет»."
L["Your action bars and their buttons."] = "Ваши панели команд и их кнопки."
L["Your attacks don't land critical hits yet."] = "Ваши атаки пока не наносят критических ударов."
L["Your attacks and spells miss %.1f%% less often."] = "Ваши атаки и заклинания промахиваются на %.1f%% реже."
L["Your bags are full."] = "Ваши сумки полны."
L["Your bank and your other characters' bags, from anywhere."] = "Ваш банк и сумки других персонажей, откуда угодно."
L["Your bank from anywhere, and your other characters' bags and banks."] = "Ваш банк откуда угодно, а также сумки и банки других персонажей."
L["Your bindings"] = "Ваши назначения клавиш"
L["Your buffs"] = "Ваши положительные эффекты"
L["Your buffs and debuffs."] = "Ваши положительные и отрицательные эффекты."
L["Your buffs grow direction"] = "Направление роста ваших положительных эффектов"
L["Your buffs left / right"] = "Ваши положительные эффекты влево / вправо"
L["Your buffs position"] = "Положение ваших положительных эффектов"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "Ваши положительные эффекты по цветным группам; отрицательные — с каймой по типу."
L["Your buffs up / down"] = "Ваши положительные эффекты вверх / вниз"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "Ваши эффекты, мини-карта и инфопанель, трекер заданий и чат тоже угасают, оставляя только костер и мир. Наведите курсор на любой из них, чтобы увидеть его."
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "Ваши положительные эффекты по цветным категориям. Правый щелчок по эффекту отменяет его; Shift-щелчок переносит его в другую категорию. Полоса находится рядом с инфопанелью; чтобы переместить ее, выключите «Прикрепить к инфопанели»."
L["Your cast bar's color for a moment after your cast is interrupted."] = "Цвет вашего индикатора заклинаний сразу после прерывания."
L["Your cast bar's color while you cast."] = "Цвет вашего индикатора заклинаний во время применения."
L["Your cast bar's color while you channel."] = "Цвет вашего индикатора заклинаний во время поддержания."
L["Your cast bar's colors"] = "Цвета вашего индикатора заклинаний"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "Ваши заклинания цветом вашего класса или градиентом класса при двухцветной заливке. Не с градиентом Daylight."
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "Окно персонажа: экипировка, модель, характеристики и другие страницы. Открывается клавишей C, как всегда."
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "Ваш чат также возвращается при следующем входе этим персонажем, под серой линией со временем вашего ухода."
L["Your class"] = "Ваш класс"
L["Your class can heal; pick Healer if you do."] = "Ваш класс умеет исцелять; выберите «Лекарь», если вы лечите."
L["Your class's pick"] = "Выбор вашего класса"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "«Выбор вашего класса» следует за вашим классом на каждом персонаже. Выберите другой, чтобы следить за ним."
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "Ваши периодические заклинания: конец здоровья, которое они еще снимут, затеняется темнее."
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Colors."] = "Ваши периодические заклинания: конец здоровья, которое они еще снимут, затеняется темнее. Цвет — в Рамки портретов > Цвета."
L["Your debuffs"] = "Ваши отрицательные эффекты"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "Ваши отрицательные эффекты, контроль и положительные эффекты, которые можно снять, на индикаторах противников."
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "Индикатор заклинаний фокуса заполняется справа. Не когда он внутри рамки."
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "Заклинания вашего фокуса, пока длятся. Использует цвета индикатора заклинаний цели."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "Собственный цвет здоровья вашей рамки, чтобы она отличалась от других. «Как на странице \"Цвета\"» следует общему для всех рамок цвету; градиент Daylight — от синего к оранжевому, как на логотипе."
L["Your frames per second beside the clock."] = "Количество кадров в секунду рядом с часами."
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "Количество кадров в секунду рядом с часами. Наведите курсор, чтобы увидеть задержку, нагрузку модификаций на процессор и память."
L["Your friends, recent allies, friend requests and the raid, in one window, in DaylightUI style."] = "Ваши друзья, недавние союзники, запросы дружбы и рейд — в одном окне, в стиле DaylightUI."
L["Your group is too big for a %d-player activity."] = "Ваша группа слишком велика для занятия на %d игроков."
L["Your guild's officer chat."] = "Чат офицеров вашей гильдии."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals or shields shows none."] = "Ваши периодические исцеления и щиты, все, что вы применяете, или все сразу. Класс без исцелений и щитов ничего не показывает."
L["Your health and mana come back faster while you're not fighting or casting."] = "Здоровье и мана восполняются быстрее, пока вы не сражаетесь и не применяете заклинания."
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "Ваши здоровье и ресурс прямо под персонажем, как личный индикатор из Legion у ваших ног."
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "Ваша полоса здоровья, ресурс под ней и, для разбойников и друидов, приемы серии прямо под персонажем. Следует за камерой при приближении."
L["Your health. Each point adds about 10; you have %.0f."] = "Ваше здоровье. Каждая единица дает около 10; у вас %.0f."
L["Your last name after your first, at the top of the window."] = "Ваша фамилия после имени, вверху окна."
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in DaylightUI style."] = "Ваши письма, отправка и заработок на почте и в аукционном доме — в одном окне, в стиле DaylightUI."
L["Your listing"] = "Ваша заявка"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "Ваша правая рука бьет каждые %.2f с. Меньше — быстрее."
L["Your mana, rage or energy under the health bar."] = "Ваша мана, ярость или энергия под полосой здоровья."
L["Your melee attacks hit harder: Strength adds attack power."] = "Ваши атаки ближнего боя бьют сильнее: сила увеличивает силу атаки."
L["Your own buffs and heals over time, in a row above the name."] = "Ваши положительные эффекты и периодические исцеления, в ряд над именем."
L["Your own color"] = "Ваш цвет"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "Ваша собственная раскладка восстановлений: каждое заклинание, которое отслеживает трекер восстановления, в виде значка или полосы, размещенное где угодно и состыкованное. Одна раскладка на набор талантов, для этого персонажа."
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "Ваша рамка находится вместе с рамками группы. Если выключено, показываются только остальные участники."
L["Your own frame."] = "Ваша рамка."
L["Your own groups"] = "Ваши группы"
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in DaylightUI's look. Saved for this character."] = "Ваша раскладка на этом персонаже. Если выключено, заклинания этого персонажа показываются там, где их ставит игра, но в стиле DaylightUI. Сохраняется для этого персонажа."
L["Your own tile sits with the raid's. When off, only the rest of the raid shows."] = "Ваша плитка находится вместе с плитками рейда. Если выключено, показываются только остальные участники рейда."
L["Your party and raid as square tiles under you, dispels easy to spot."] = "Ваша группа и рейд квадратными плитками под вами, рассеивания легко заметить."
L["Your party: bars like your own frame, or square tiles. Set how they line up, what shows, and move them as one in unlock mode."] = "Ваша группа: полосы как у вашей рамки или квадратные плитки. Задайте, как они выстраиваются, что показывают, и перемещайте их вместе в режиме открепления."
L["Your pet"] = "Ваш питомец"
