L["Your pet's damage"] = "Урон вашего питомца"
L["Your pet's or totem's hits too."] = "Удары вашего питомца или тотема тоже."
L["Your picks are saved into %s."] = "Ваш выбор сохраняется в %s."
L["Your portrait ring, or your name tab without a portrait, turns red while you're in combat."] = "Кольцо портрета или вкладка имени без портрета краснеет, пока вы в бою."
L["Your priority quest is the one the marker and arrow lead to."] = "Приоритетное задание — то, к которому ведут маркер и стрелка."
L["Your profession's recipes in one window, in DaylightUI style."] = "Рецепты вашей профессии в одном окне, в стиле DaylightUI."
L["Your quest tracker."] = "Ваш трекер заданий."
L["Your quests in the DaylightUI look, with item buttons and smooth motion."] = "Ваши задания в стиле DaylightUI, с кнопками предметов и плавным движением."
