L["Your shots don't land critical hits yet."] = "Ваши выстрелы пока не наносят критических ударов."
L["Your spellbook and talents in one window, in DaylightUI style."] = "Ваша книга заклинаний и таланты в одном окне, в стиле DaylightUI."
L["Your spells don't land critical hits yet."] = "Ваши заклинания пока не наносят критических ударов."
