L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "Когда кто-то пишет ваше имя там, где общаются игроки, оно подсвечивается акцентным цветом, а вкладка с ним начинает светиться."
L["When the away message answers."] = "Когда отвечает сообщение «Нет на месте»."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "Где появляется поле ввода. «Под панелью» оставляет для него полосу под чатом, чтобы оно никогда не закрывало текст. «Внизу» – окно чата Daylight поднимает сообщения над полем, пока вы печатаете."
L["Whisper tiles"] = "Плитки шепота"
L["Whisper tiles show"] = "Плитки шепота показывают"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "Шепот – часть окна чата Daylight: /dui chat daylight, чтобы им пользоваться."
L["Whispers open on the"] = "Шепот открывается"
L["Whispers show in"] = "Где показывать шепот"
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "Если поле ввода внизу: пока вы печатаете, сообщения сдвигаются вверх, а поле ввода оказывается под ними и не закрывает ни строки."
L["Words to light up"] = "Подсвечиваемые слова"
L["Words to light up, separated by commas"] = "Подсвечиваемые слова через запятую"
L["XP, reputation and skills"] = "Опыт, репутация и навыки"
L["not a table"] = "не таблица"
L["show"] = "показать"
L["A bar of its own for the faction you're watching. While it's on, the experience bar no longer turns to reputation when you gain some."] = "Отдельный индикатор для отслеживаемой фракции. Пока он включен, индикатор опыта больше не переключается на репутацию при ее получении."
L["Game window skins"] = "Оформление окон игры"
L["How far through the standing you are, e.g. 60%."] = "Насколько вы продвинулись в текущем отношении, например 60%."
L["How tall the reputation bar is."] = "Высота индикатора репутации."
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "Ширина индикатора репутации. Перетаскивание его угла в режиме перемещения тоже меняет ее."
L["More windows"] = "Другие окна"
L["Reputation Bar"] = "Индикатор репутации"
L["Reputation bar"] = "Индикатор репутации"
L["Reputation bar gradient"] = "Градиент индикатора репутации"
L["Reputation bar height"] = "Высота индикатора репутации"
L["Reputation bar width"] = "Ширина индикатора репутации"
L["Reputation details position"] = "Положение подробностей репутации"
L["Reputation text size"] = "Размер текста репутации"
L["Show a separate reputation bar"] = "Показывать отдельный индикатор репутации"
L["Show reputation as text"] = "Показывать репутацию текстом"
L["Show reputation percent"] = "Показывать процент репутации"
L["Show the faction's name"] = "Показывать название фракции"
L["Size of the text on the reputation bar. Its font is the experience bar's."] = "Размер текста на индикаторе репутации. Шрифт — как у индикатора опыта."
L["Spellbook, inspect, professions, group finder, mailbox, social and Legacy: each window's switch, its size and its own extras."] = "Книга заклинаний, осмотр, профессии, поиск группы, почтовый ящик, общение и Наследие: переключатель каждого окна, его размер и особые настройки."
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "Индикатор переходит от темного к яркому в цветах своего отношения; их можно изменить на странице «Градиенты»."
L["The faction's name on the bar."] = "Название фракции на индикаторе."
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "Числа на индикаторе, например 1,800 / 3,000."
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "Отслеживаемая репутация, всегда, на собственном индикаторе. Фракцию выбирают на странице «Репутация» в окне персонажа. Перемещайте его в режиме перемещения; тяните за угол, чтобы изменить размер."
L["Welcome back, %s"] = "С возвращением, %s"
